/*
 * #version 450
 * #extension GL_EXT_shader_atomic_float : require
 * layout(local_size_x = 64) in;
 * layout(std430, binding = 0) buffer A {
 *     uint counter;
 *     int smin;
 *     int smax;
 *     uint umin;
 *     uint umax;
 *     uint andv;
 *     uint orv;
 *     uint xorv;
 *     uint exch;
 *     uint cas;
 *     uint hist[8];
 *     uint seen[256];
 *     float fsum;
 * } a;
 * shared uint lhist[8];
 * void main()
 * {
 *     uint i = gl_GlobalInvocationID.x;
 *     uint l = gl_LocalInvocationID.x;
 *     if (l < 8u)
 *         lhist[l] = 0u;
 *     barrier();
 *     uint ticket = atomicAdd(a.counter, 1u);
 *     a.seen[ticket] = i + 1u;
 *     int si = int(i) - 100;
 *     atomicMin(a.smin, si);
 *     atomicMax(a.smax, si);
 *     atomicMin(a.umin, i + 5u);
 *     atomicMax(a.umax, i * 3u);
 *     atomicAnd(a.andv, ~(1u << (i % 32u)));
 *     atomicOr(a.orv, 1u << (i % 32u));
 *     atomicXor(a.xorv, i);
 *     atomicExchange(a.exch, 42u);
 *     uint old = a.cas, assumed;
 *     do {
 *         assumed = old;
 *         old = atomicCompSwap(a.cas, assumed, assumed + 2u);
 *     } while (old != assumed);
 *     atomicAdd(a.fsum, 0.5);
 *     atomicAdd(lhist[i % 8u], 1u);
 *     barrier();
 *     if (l < 8u)
 *         atomicAdd(a.hist[l], lhist[l]);
 * }
 */
