/*
 * #version 450
 * layout(local_size_x = 4) in;
 * layout(std430, binding = 0) writeonly buffer Out { vec4 f[]; };
 * struct Inner { vec2 a; int k[2]; };
 * struct Outer { Inner items[3]; float w; };
 * vec3 gcolor = vec3(0.25, 0.5, 0.75); // Private, initialized
 * int gcount;                          // Private
 * void bump(int n)
 * {
 *     gcount += n;
 *     gcolor *= 2.0;
 * }
 * void main()
 * {
 *     uint t = gl_GlobalInvocationID.x;
 *     int i = int(t);
 *     float fi = float(t);
 *     gcount = 1;
 *     bump(i);
 *     vec4 a = vec4(fi, 2.0, -fi, 0.5 * fi);
 *     vec4 b = vec4(1.0, fi, 0.0, 1.5);
 *     bvec4 lt = lessThan(a, b);
 *     bvec4 ge = greaterThanEqual(a, b);
 *     vec4 sel = mix(a, b, lt);
 *     vec4 sel2 = (t & 1u) != 0u ? a : b;
 *     vec4 v = a;
 *     v.zx = vec2(7.0, 8.0);
 *     v[t % 4u] = 100.0;
 *     float dyn = a[(t + 1u) % 4u];
 *     mat3 m = mat3(1.0);
 *     m[t % 3u] = vec3(fi, fi + 1.0, fi + 2.0);
 *     m[(t + 1u) % 3u][t % 3u] = -5.0;
 *     mat3 m2 = m * 2.0 + m - mat3(0.5);
 *     mat3 m3 = matrixCompMult(m, m2);
 *     ivec3 iv = ivec3(i, -i, 3) * 3;
 *     uvec3 uv = uvec3(t, 7u, 0xf0u);
 *     uvec3 sh = (uv << ivec3(1, 2, 3)) | (uvec3(iv) >> uvec3(1u));
 *     Outer o;
 *     for (int k = 0; k < 3; k++) {
 *         o.items[k].a = vec2(float(k), fi);
 *         o.items[k].k[0] = k;
 *         o.items[k].k[1] = -k;
 *     }
 *     o.w = 3.0;
 *     Outer o2 = o;
 *     o2.items[t % 3u].k[1] = 42;
 *     f[t * 12u + 0u] = vec4(lt) + 2.0 * vec4(ge);
 *     f[t * 12u + 1u] = vec4(any(lt), all(ge), any(not(ge)), all(equal(a, a)));
 *     f[t * 12u + 2u] = sel;
 *     f[t * 12u + 3u] = sel2;
 *     f[t * 12u + 4u] = v;
 *     f[t * 12u + 5u] = vec4(dyn, gcolor);
 *     f[t * 12u + 6u] = vec4(m[0], float(gcount));
 *     f[t * 12u + 7u] = vec4(m3[1], m3[2].z);
 *     f[t * 12u + 8u] = vec4(iv, float(notEqual(uv, uvec3(7u)).x));
 *     f[t * 12u + 9u] = vec4(sh, 0.0);
 *     f[t * 12u + 10u] = vec4(o2.items[t % 3u].k[1], o2.items[(t + 1u) % 3u].k[1], o2.items[2].a.y, o2.w);
 *     f[t * 12u + 11u] = vec4(isnan(vec2(a.x / 0.0 - a.x / 0.0, 1.0)), isinf(vec2(1.0 / (fi - fi), 2.0)));
 * }
 */
