 *     o[n++] = int(usubBorrow(ua, ub, borrow)) + int(borrow);
 *     umulExtended(ua, ub, hi, lo);
 *     o[n++] = int(hi ^ lo);
 *     imulExtended(a, b, shi, slo);
 *     o[n++] = shi + slo;
 *     o[n++] = bitfieldExtract(a, 3, 9);
 *     o[n++] = int(bitfieldExtract(ua, 5, 12));
 *     o[n++] = bitfieldInsert(a, b, 4, 8);
 *     o[n++] = int(bitfieldReverse(ua));
 *     o[n++] = bitCount(a) + bitCount(ub);
 *     o[n++] = findLSB(a) * 100 + findLSB(ub);
 *     o[n++] = findMSB(a) * 100 + findMSB(ub);
