/* Buffer device addresses (GL_EXT_buffer_reference): pointers in push
 * constants and in memory, a linked list followed through a function
 * parameter, uint64_t and uvec2 conversions, address arithmetic, atomics
 * and stored pointers (spv_bda_opt: also spirv-opt -O).
 *
 * #version 450
 * #extension GL_EXT_buffer_reference : require
 * #extension GL_EXT_buffer_reference2 : require
 * #extension GL_EXT_buffer_reference_uvec2 : require
 * #extension GL_EXT_shader_explicit_arithmetic_types_int64 : require
 * layout(local_size_x = 32) in;
 * layout(buffer_reference) buffer Node;
 * layout(buffer_reference, std430, buffer_reference_align = 16) buffer Node { vec4 value; Node next; uint tag; };
 * layout(buffer_reference, std430, buffer_reference_align = 4) buffer Counter { uint count; };
 * layout(buffer_reference, std430, buffer_reference_align = 4) buffer Out { uint data[]; };
 * layout(buffer_reference, std430, buffer_reference_align = 4) buffer Floats { float f; };
 * layout(buffer_reference, std430, buffer_reference_align = 8) buffer Links { Node ptrs[]; };
 * layout(push_constant) uniform Push { Node head; uint64_t out_addr; uvec2 counter_addr; Links links; uint n; } pc;
 * float sum_list(Node n, uint max_steps)
 * {
 *     float s = 0.0;
 *     for (uint k = 0u; k < max_steps && uint64_t(n) != 0ul; k++) {
 *         s += n.value.x * float(n.tag);
 *         n = n.next;
 *     }
 *     return s;
 * }
 * void main()
 * {
 *     uint i = gl_GlobalInvocationID.x;
 *     if (i >= pc.n)
 *         return;
 *     Out o = Out(pc.out_addr);
 *     o.data[i] = uint(sum_list(pc.head, i + 1u));
 *     Counter c = Counter(pc.counter_addr);
 *     atomicAdd(c.count, 1u);
 *     Floats f = Floats(uint64_t(pc.head) + 4ul * uint64_t(i % 4u));
 *     o.data[pc.n + i] = floatBitsToUint(f.f);
 *     Floats f2 = f + 1;
 *     o.data[2u * pc.n + i] = uvec2(pc.links).x == 0u ? 0u : floatBitsToUint(f2.f);
 *     pc.links.ptrs[i] = (i & 1u) != 0u ? pc.head : pc.head.next;
 * }
 */
