/*
 * #version 450
 * #extension GL_EXT_shader_image_load_formatted : require
 * layout(local_size_x = 4, local_size_y = 4) in;
 * layout(set = 0, binding = 0, rgba32f) uniform readonly image2D src;
 * layout(set = 0, binding = 1, rgba32f) uniform writeonly image2D dst;
 * layout(set = 0, binding = 2, r32ui) uniform uimage3D vol;
 * layout(set = 0, binding = 3, rgba16f) uniform image2DArray layers;
 * layout(set = 0, binding = 4, rgba8) uniform imageCube cube;
 * layout(set = 0, binding = 5, r32i) uniform iimage1D line;
 * layout(set = 0, binding = 6) uniform image2D noformat;
 * layout(set = 0, binding = 7, rgba32f) uniform imageCubeArray cubes;
 * layout(std430, set = 0, binding = 8) writeonly buffer Out { vec4 back[96]; ivec4 sizes[3]; };
 * void main()
 * {
 *     ivec2 p = ivec2(gl_LocalInvocationID.xy);
 *     int idx = p.x + 4 * p.y;
 *     imageStore(dst, p, imageLoad(src, p) * 2.0 + vec4(p, 0.0, 0.0));
 *     for (int z = 0; z < 4; z++)
 *         imageStore(vol, ivec3(p, z), uvec4(imageLoad(vol, ivec3(p, z)).x * 3u + uint(z)));
 *     for (int l = 0; l < 3; l++)
 *         imageStore(layers, ivec3(p, l), imageLoad(layers, ivec3(p, l)) + vec4(float(l)));
 *     for (int f = 0; f < 6; f++) {
 *         imageStore(cube, ivec3(p, f), vec4(float(f) / 8.0, float(p.x) / 4.0, float(p.y) / 4.0, 1.0));
 *         back[f * 16 + idx] = imageLoad(cube, ivec3(p, f));
 *     }
 *     imageStore(line, idx, ivec4(-idx));
 *     imageStore(noformat, p, imageLoad(noformat, p).wzyx);
 *     if (p.x < 2 && p.y < 2)
 *         for (int z = 0; z < 12; z++)
 *             imageStore(cubes, ivec3(p, z), vec4(float(z), float(p.x), float(p.y), 0.5));
 *     if (idx == 0) {
 *         sizes[0] = ivec4(imageSize(src), imageSize(vol).z, imageSize(layers).z);
 *         sizes[1] = ivec4(imageSize(cube), imageSize(line), imageSize(cubes).z);
 *         sizes[2] = ivec4(imageSize(noformat), imageSize(cubes).xy);
 *     }
 * }
 */
