/* Whole structs holding matrices Metal cannot store natively (std140 mat2,
 * arrays of mat3x2, row-major), converted to and from their value types. */
static void check_matlayout(const uint32_t *words, size_t count)
{
    static const struct { uint32_t offset; float v[3]; uint32_t n; } b_want[] = {
        { 0, { 1, 2 }, 2 }, { 16, { 3, 4 }, 2 }, { 32, { 5 }, 1 },                      /* b.s.m, b.s.f */
        { 48, { 6, 0 }, 2 }, { 64, { 0, 6 }, 2 }, { 80, { 0, 0 }, 2 },                  /* b.s.r[0] columns */
        { 96, { 7, 0 }, 2 }, { 112, { 0, 7 }, 2 }, { 128, { 0, 0 }, 2 },               /* b.s.r[1] */
        { 144, { 1, 2 }, 2 }, { 160, { 3, 4 }, 2 }, { 176, { 5 }, 1 },                  /* b.t */
        { 192, { 6, 0 }, 2 }, { 208, { 0, 6 }, 2 }, { 224, { 0, 0 }, 2 },
        { 240, { 7, 0 }, 2 }, { 256, { 0, 7 }, 2 }, { 272, { 8, 9 }, 2 },
        { 288, { 1, 2 }, 2 }, { 304, { 3, 4 }, 2 }, { 320, { 1, 2 }, 2 }, { 336, { 3, 4 }, 2 }, /* b.arr */
    };
    static const struct { uint32_t offset; float v[3]; uint32_t n; } r_want[] = {
        { 0, { 1, 3 }, 2 }, { 16, { 2, 4 }, 2 }, { 32, { 5 }, 1 },   /* rb.s.m rows, rb.s.f */
        { 48, { 6, 0, 0 }, 3 }, { 64, { 0, 10, 0 }, 3 },           /* rb.s.r[0] rows */
        { 80, { 7, 0, 8 }, 3 }, { 96, { 0, 7, 9 }, 3 },            /* rb.s.r[1] rows */
    };
    struct pvk_msl_result res;
    struct mt_buffer bb, rb;
    struct mt_binding b[2];
    uint32_t i, k;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    bb = mt_buffer(352, NULL, 0);
    rb = mt_buffer(112, NULL, 0);
    poison(bb.data, bb.size, POISON);
    poison(rb.data, rb.size, POISON);
    b[0] = bind(0, 0, &bb);
    b[1] = bind(0, 1, &rb);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < PVK_ARRAY_SIZE(b_want); i++)
        for (k = 0; k < b_want[i].n; k++)
            EXPECT(get_f32(bb.data, b_want[i].offset + 4 * k) == b_want[i].v[k], "b byte %u: %g, want %g",
                   b_want[i].offset + 4 * k, get_f32(bb.data, b_want[i].offset + 4 * k), b_want[i].v[k]);
    for (i = 0; i < PVK_ARRAY_SIZE(r_want); i++)
        for (k = 0; k < r_want[i].n; k++)
            EXPECT(get_f32(rb.data, r_want[i].offset + 4 * k) == r_want[i].v[k], "rb byte %u: %g, want %g",
                   r_want[i].offset + 4 * k, get_f32(rb.data, r_want[i].offset + 4 * k), r_want[i].v[k]);
    CHECK(bad == 0);
    mt_buffer_free(&bb);
    mt_buffer_free(&rb);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_matlayout(void)
{
    check_matlayout(spv_matlayout, PVK_ARRAY_SIZE(spv_matlayout));
}

static void test_matlayout_opt(void)
{
    check_matlayout(spv_matlayout_opt, PVK_ARRAY_SIZE(spv_matlayout_opt));
}

/* Stores into std140 storage: exact bytes, padding left alone (except
 * inside elements written whole). */
static void test_store140(void)
{
    static const struct { uint32_t word; float v; } stores[] = {
        { 0, 1 }, { 4, 2 }, { 8, 3 },                                         /* arr */
        { 12, 4 }, { 13, 5 }, { 16, 6 }, { 17, 8 },                          /* m2 */
        { 20, 10 }, { 21, 20 }, { 22, 16 }, { 24, 11 }, { 25, 21 }, { 26, 17 }, /* rm rows */
        { 28, 12 }, { 29, 22 }, { 30, 18 },
        { 32, 30 }, { 33, 32 }, { 36, 34 }, { 37, 33 },                      /* rm2 rows */
        { 40, 44 }, { 44, 45 }, { 45, 46 }, { 46, 47 },                      /* st[0] */
        { 48, 40 }, { 52, 41 }, { 53, 42 }, { 54, 43 },                      /* st[1] */
        { 60, 50 }, { 61, 51 }, { 62, 52 },                                  /* v[1] */
        { 68, 64 }, { 69, 65 },                                              /* marr[0][1] */
        { 72, 60 }, { 73, 61 }, { 76, 62 }, { 77, 63 },                      /* marr[1] */
    };
    static const uint32_t dont_care[] = { 41, 42, 43, 47, 63 }; /* st[0] padding, v[1] padding */
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    uint32_t want[80], i, j;
    int32_t k = 1;
    id pso;

    MT_BUILD(spv_store140, NULL, res, pso);
    buf = mt_buffer(320, NULL, 0);
    poison(buf.data, buf.size, 0xaaaaaaaau);
    for (i = 0; i < 80; i++)
        want[i] = 0xaaaaaaaau;
    for (i = 0; i < PVK_ARRAY_SIZE(stores); i++)
        memcpy(&want[stores[i].word], &stores[i].v, 4);
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, &k, sizeof(k), 1, 1, 1));
    bad = 0;
    for (i = 0; i < 80; i++) {
        bool skip = false;
        for (j = 0; j < PVK_ARRAY_SIZE(dont_care); j++)
            skip |= dont_care[j] == i;
        if (!skip)
            EXPECT(get_u32(buf.data, 4 * i) == want[i], "byte %u: %08x (%g), want %08x (%g)", 4 * i,
                   get_u32(buf.data, 4 * i), get_f32(buf.data, 4 * i), want[i], get_f32(want, 4 * i));
    }
    CHECK(bad == 0);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ==========================================================================
 * Control flow
 * ========================================================================== */

/* Runs a shader writing one int per thread into binding 0 and compares. */
static void check_ints(const uint32_t *words, size_t count, uint32_t threads, int (*ref)(int))
{
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    uint32_t i;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    out = mt_buffer(threads * 4, NULL, 0);
    b = bind(0, 0, &out);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, threads / res.workgroup_size[0], 1, 1));
    bad = 0;
    for (i = 0; i < threads; i++)
        EXPECT(((int *)out.data)[i] == ref((int)i), "o[%u] = %d, want %d", i, ((int *)out.data)[i], ref((int)i));
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static int ref_loops(int x)
{
    int acc = 0, i, j;
    for (i = 0; i < 20; i++) {
        if ((i & 3) == 1)
            continue;
        if (i * x > 200)
            break;
        j = 0;
        while (j < i) {
            j += 2;
            if (j == 6)
                continue;
            acc += j ^ x;
        }
        do {
            acc -= 1;
        } while (acc > 1000 && (acc & 1) == 0);
    }
    return acc;
}

static int ref_switch(int x)
{
    int r = 0, i;
    for (i = 0; i < 8; i++) {
        switch ((x + i) % 7) {
        case 0:
            r += 1;
            /* fall through */
        case 1:
            r += 10;
            break;
        case 2:
            continue;
        case 3:
        case 4:
            r *= 2;
            break;
        default:
            r -= 3;
            break;
        case 6:
            if (r > 50)
                return r;
            r += 100;
            break;
        }
        r += i;
    }
    if ((x & 3) == 0)
        r = -r;
    return r;
}

static void test_loops(void)
{
    check_ints(spv_loops, PVK_ARRAY_SIZE(spv_loops), 256, ref_loops);
}

static void test_loops_opt(void)
{
    check_ints(spv_loops_opt, PVK_ARRAY_SIZE(spv_loops_opt), 256, ref_loops);
}

static void test_switch(void)
{
    check_ints(spv_switch, PVK_ARRAY_SIZE(spv_switch), 256, ref_switch);
}

/* spirv-opt turns the early return into a loop break from inside the
 * switch, and gives the fallthrough case a phi. */
static void test_switch_opt(void)
{
    check_ints(spv_switch_opt, PVK_ARRAY_SIZE(spv_switch_opt), 256, ref_switch);
}

static float ref_process(float v, float scale)
{
    float acc = 0.0f, x;
    int s;
    x = v - floorf(v); /* accumulate(acc, fract(v), s) */
    if (x < 0.0f) {
        s = -1;
        acc -= x;
    } else {
        s = 1;
        acc += x * scale;
    }
    x = -floorf(v); /* accumulate(acc, -floor(v), s) */
    if (x < 0.0f) {
        s = -1;
        acc -= x;
    } else {
        s = 1;
        acc += x * scale;
    }
    if (s > 0) {
        if (acc > 2.0f)
            return acc;
        else if (acc < -2.0f)
            return -acc;
    }
    return acc + (float)s;
}

/* Helper functions with inout/out parameters, early returns, a struct
 * return value, and globals (buffer, push constant, shared array). */
static void check_funcs(const uint32_t *words, size_t count)
{
    struct pvk_msl_result res;
    struct mt_buffer data;
    struct mt_binding b;
    float in[128], scale = 1.5f;
    uint32_t i;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    CHECK(res.threadgroup_memory_size == 128);
    for (i = 0; i < 128; i++)
        in[i] = (float)i * 0.37f - 20.0f;
    data = mt_buffer(sizeof(in), in, sizeof(in));
    b = bind(0, 0, &data);
    CHECK(mt_dispatch(pso, &res, &b, 1, &scale, sizeof(scale), 4, 1, 1));
    bad = 0;
    for (i = 0; i < 128; i++) {
        float want = ref_process(in[i], scale) + in[(i & ~31u) + ((i + 1) & 31u)];
        EXPECT(mt_near(((float *)data.data)[i], want, 1e-5), "v[%u] = %g, want %g", i, ((float *)data.data)[i], want);
    }
    CHECK(bad == 0);
    mt_buffer_free(&data);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_funcs(void)
{
    check_funcs(spv_funcs, PVK_ARRAY_SIZE(spv_funcs));
}

static void test_funcs_opt(void)
{
    check_funcs(spv_funcs_opt, PVK_ARRAY_SIZE(spv_funcs_opt));
}

/* ==========================================================================
 * Workgroups, barriers, atomics
 * ========================================================================== */

static void check_reduce(const uint32_t *words, size_t count)
{
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[2];
    float x[16 * 128];
    uint32_t i, g;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    CHECK(res.workgroup_size[0] == 128 && res.threadgroup_memory_size == 512);
    for (i = 0; i < 16 * 128; i++)
        x[i] = (float)(i % 17);
    in = mt_buffer(sizeof(x), x, sizeof(x));
    out = mt_buffer(16 + 16 * 4, NULL, 0);
    b[0] = bind(0, 0, &in);
    b[1] = bind(0, 1, &out);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 16, 1, 1));
    bad = 0;
    for (g = 0; g < 16; g++) {
        float sum = 0;
        for (i = 0; i < 128; i++)
            sum += x[g * 128 + i];
        EXPECT(get_f32(out.data, 16 + 4 * g) == sum, "sums[%u] = %g, want %g", g, get_f32(out.data, 16 + 4 * g), sum);
    }
    /* thread 130: NumWorkgroups.xy, LocalInvocationIndex, WorkgroupId.x */
    EXPECT(get_u32(out.data, 0) == 16 && get_u32(out.data, 4) == 1 && get_u32(out.data, 8) == 2 &&
               get_u32(out.data, 12) == 1,
           "info = %u %u %u %u", get_u32(out.data, 0), get_u32(out.data, 4), get_u32(out.data, 8), get_u32(out.data, 12));
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_reduce(void)
{
    check_reduce(spv_reduce, PVK_ARRAY_SIZE(spv_reduce));
}

static void test_reduce_opt(void)
{
    check_reduce(spv_reduce_opt, PVK_ARRAY_SIZE(spv_reduce_opt));
}

static void test_atomics(void)
{
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    uint32_t *a, i, seen[256];
    id pso;

    MT_BUILD(spv_atomics, NULL, res, pso);
    buf = mt_buffer((10 + 8 + 256 + 1) * 4, NULL, 0);
    a = buf.data;
    a[1] = 0x7fffffffu; /* smin */
    a[2] = 0x80000000u; /* smax */
    a[3] = 0xffffffffu; /* umin */
    a[5] = 0xffffffffu; /* andv */
    a[7] = 0x12345678u; /* xorv */
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 4, 1, 1));
    CHECK(a[0] == 256);
    CHECK((int32_t)a[1] == -100);
    CHECK((int32_t)a[2] == 155);
    CHECK(a[3] == 5);
    CHECK(a[4] == 765);
    CHECK(a[5] == 0);
    CHECK(a[6] == 0xffffffffu);
    CHECK(a[7] == 0x12345678u); /* xor of 0..255 is 0 */
    CHECK(a[8] == 42);
    CHECK(a[9] == 512); /* compare-and-swap loop, +2 per thread */
    CHECK(get_f32(a, 4 * 274) == 128.0f); /* float atomicAdd */
    bad = 0;
    for (i = 0; i < 8; i++)
        EXPECT(a[10 + i] == 32, "hist[%u] = %u", i, a[10 + i]);
    memset(seen, 0, sizeof(seen)); /* every ticket handed out exactly once */
    for (i = 0; i < 256; i++) {
        uint32_t v = a[18 + i];
        EXPECT(v >= 1 && v <= 256 && !seen[v - 1], "seen[%u] = %u", i, v);
        if (v >= 1 && v <= 256)
            seen[v - 1] = 1;
    }
    CHECK(bad == 0);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

