/* frexp and modf of 3-vectors (FrexpStruct, ModfStruct: their 3-vector
 * members are packed, so the out parameter goes through a temporary). */
static void test_frexp_modf3(void)
{
    static const float x[4] = { 8.0f, 0.75f, -3.5f, 0.0f };
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    float io[20];
    const float *m, *f, *w;
    const int32_t *e;
    id pso;

    MT_BUILD(spv_frexp_modf3, NULL, res, pso);
    memset(io, 0, sizeof(io));
    memcpy(io, x, sizeof(x));
    buf = mt_buffer(sizeof(io), io, sizeof(io));
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    m = (const float *)buf.data + 4;
    e = (const int32_t *)buf.data + 8;
    f = (const float *)buf.data + 12;
    w = (const float *)buf.data + 16;
    CHECK(m[0] == 0.5f && m[1] == 0.75f && m[2] == -0.875f);
    CHECK(e[0] == 4 && e[1] == 0 && e[2] == 2);
    CHECK(f[0] == 0.0f && f[1] == 0.75f && f[2] == -0.5f);
    CHECK(w[0] == 8.0f && w[1] == 0.0f && w[2] == -3.0f);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}


