/* samplerBuffer: a sampled image of a texel buffer is the texel buffer (a
 * uniform texel buffer descriptor), fetched and sized like one. */
static void test_sampler_buffer(void)
{
    struct pvk_msl_result res;
    id pso;

    MT_BUILD(spv_sampler_buffer, NULL, res, pso);
    CHECK(res.resource_count == 2 && res.resources[1].binding == 1 &&
          res.resources[1].type == VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER && res.resources[1].stride == 8);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ==========================================================================
 * Push constants and specialization
 * ========================================================================== */

static void test_push_constants(void)
{
    unsigned char push[80];
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    uint32_t i, k;
    id pso;

    MT_BUILD(spv_push, NULL, res, pso);
    CHECK(res.has_push_constants && res.push_constant_offset == 16 && res.push_constant_size == 60);
    memset(push, 0xff, sizeof(push)); /* bytes before offset 16 are not the block's */
    for (k = 0; k < 4; k++)
        put_f32(push, 16 + 4 * k, 1.0f + (float)k); /* color */
    for (k = 0; k < 4; k++)
        put_f32(push, 32 + 4 * k, 5.0f + (float)k); /* m: columns (5,6) (7,8), 8 bytes apart */
    for (k = 0; k < 3; k++)
        put_f32(push, 48 + 4 * k, 9.0f + (float)k); /* v */
    put_f32(push, 60, 12);
    put_u32(push, 64, 6);
    put_u32(push, 68, 13);
    put_u32(push, 72, 14);
    out = mt_buffer(8 * 16, NULL, 0);
    b = bind(0, 0, &out);
    CHECK(mt_dispatch(pso, &res, &b, 1, push, sizeof(push), 1, 1, 1));
    bad = 0;
    for (i = 0; i < 8; i++) {
        const float *o = (const float *)out.data + 4 * i;
        float f = (float)i;
        if (i >= 6) {
            EXPECT(o[0] == 0 && o[1] == 0 && o[2] == 0 && o[3] == 0, "thread %u wrote", i);
            continue;
        }
        EXPECT(o[0] == 1 * f + 5 * f + 7 && o[1] == 2 * f + 6 * f + 8 && o[2] == 3 * f + 11 * 12 &&
                   o[3] == 4 * f + (float)(13 + (i & 1)),
               "o[%u] = %g %g %g %g", i, o[0], o[1], o[2], o[3]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void run_spec(const struct pvk_msl_options *options, uint32_t wg, int scale, bool negate, float bias,
                     uint32_t count)
{
    struct pvk_msl_result res;
    struct mt_buffer data;
    struct mt_binding b;
    float in[128];
    uint32_t i, n = 128;
    id pso;

    REQUIRE(mt_translate(spv_spec, PVK_ARRAY_SIZE(spv_spec), options, &res));
    CHECK(res.workgroup_size[0] == wg && res.workgroup_size[1] == 1 && res.workgroup_size[2] == 1);
    CHECK(res.threadgroup_memory_size == 4 * wg);
    CHECK(res.spec_constant_count == 5);
    for (i = 0; i < res.spec_constant_count && i < 5; i++) {
        const struct pvk_msl_spec_constant *sc = &res.spec_constants[i];
        switch (sc->id) {
        case 0:
            CHECK(sc->type == PVK_MSL_SCALAR_UINT && sc->default_value == 1 && sc->value == wg);
            break;
        case 1:
            CHECK(sc->type == PVK_MSL_SCALAR_INT && sc->default_value == 3 && sc->value == (uint32_t)scale);
            break;
        case 2:
            CHECK(sc->type == PVK_MSL_SCALAR_BOOL && sc->default_value == 0 && sc->value == (negate ? 1u : 0u));
            break;
        case 3: {
            float f;
            uint32_t bits = (uint32_t)sc->value;
            memcpy(&f, &bits, 4);
            CHECK(sc->type == PVK_MSL_SCALAR_FLOAT && sc->width == 32 && f == bias);
            break;
        }
        case 4:
            CHECK(sc->type == PVK_MSL_SCALAR_UINT && sc->default_value == 4 && sc->value == count);
            break;
        default:
            CHECK(!"unexpected spec constant id");
        }
    }
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    for (i = 0; i < n; i++)
        in[i] = (float)i * 0.5f;
    data = mt_buffer(sizeof(in), in, sizeof(in));
    b = bind(0, 0, &data);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, n / wg, 1, 1));
    bad = 0;
    for (i = 0; i < n; i++) {
        uint32_t l = i % wg;
        float v = in[i] * (float)scale + bias + (float)(wg - 1 - l) + (float)(count * 2 + 1) + (float)wg;
        if (negate)
            v = -v;
        EXPECT(((float *)data.data)[i] == v, "data[%u] = %g, want %g", i, ((float *)data.data)[i], v);
    }
    CHECK(bad == 0);
    mt_buffer_free(&data);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_spec_defaults(void)
{
    run_spec(NULL, 1, 3, false, 0.5f, 4);
}

/* Overrides every constant, including the workgroup size (LocalSizeId)
 * and the shared array sized by it. */
static void test_spec_overrides(void)
{
    struct { uint32_t wg; int32_t scale; uint32_t negate; float bias; uint32_t count; } data = { 64, 5, 1, 0.25f, 10 };
    VkSpecializationMapEntry entries[5];
    VkSpecializationInfo info;
    struct pvk_msl_options options;
    uint32_t i;

    for (i = 0; i < 5; i++) {
        entries[i].constantID = i;
        entries[i].offset = 4 * i;
        entries[i].size = 4;
    }
    info.mapEntryCount = 5;
    info.pMapEntries = entries;
    info.dataSize = sizeof(data);
    info.pData = &data;
    memset(&options, 0, sizeof(options));
    options.specialization = &info;
    run_spec(&options, 64, 5, true, 0.25f, 10);
}

static float f32_of(uint32_t bits)
{
    float f;
    memcpy(&f, &bits, 4);
    return f;
}

/* The binary16 conversions OpSpecConstantOp FConvert and QuantizeToF16 fold
 * with: rounding to nearest even (and toward zero), denormals, overflow,
 * infinities and NaNs. */
static void test_spec_half_conversions(void)
{
    static const struct { uint32_t f32, rte, rtz; } to16[] = {
        { 0x3f800000u, 0x3c00u, 0x3c00u },  /* 1.0 */
        { 0x3eaaaaabu, 0x3555u, 0x3555u },  /* 1/3: rounds down */
        { 0x3f801000u, 0x3c00u, 0x3c00u },  /* 1 + 2^-11: a tie, to even (down) */
        { 0x3f803000u, 0x3c02u, 0x3c01u },  /* 1 + 3 * 2^-11: a tie, to even (up) */
        { 0x3f801001u, 0x3c01u, 0x3c00u },  /* just above the tie */
        { 0x477fe000u, 0x7bffu, 0x7bffu },  /* 65504: the largest */
        { 0x477fefffu, 0x7bffu, 0x7bffu },  /* below 65520 */
        { 0x477ff000u, 0x7c00u, 0x7bffu },  /* 65520: infinity (to even), RTZ the largest */
        { 0x7f7fffffu, 0x7c00u, 0x7bffu },  /* FLT_MAX */
        { 0xc77ff000u, 0xfc00u, 0xfbffu },  /* -65520 */
        { 0x38800000u, 0x0400u, 0x0400u },  /* 2^-14: the smallest normal */
        { 0x387ff000u, 0x0400u, 0x03ffu },  /* 1023.75 x 2^-24: rounds up to it */
        { 0x33800000u, 0x0001u, 0x0001u },  /* 2^-24: the smallest denormal */
        { 0x33000000u, 0x0000u, 0x0000u },  /* 2^-25: a tie, to even (0) */
        { 0x33000001u, 0x0001u, 0x0000u },  /* just above it */
        { 0xb3d6bf95u, 0x8002u, 0x8001u },  /* -1e-7: -2 x 2^-24 */
        { 0x80000000u, 0x8000u, 0x8000u },  /* -0 */
        { 0x7f800000u, 0x7c00u, 0x7c00u },  /* infinity */
        { 0xff800000u, 0xfc00u, 0xfc00u },  /* -infinity */
    };
    static const struct { uint32_t f16, f32; } to32[] = {
        { 0x3c00u, 0x3f800000u }, { 0x3555u, 0x3eaaa000u }, { 0x7bffu, 0x477fe000u }, { 0x0400u, 0x38800000u },
        { 0x0001u, 0x33800000u }, { 0x03ffu, 0x387fc000u }, { 0x8200u, 0xb8000000u }, { 0x7c00u, 0x7f800000u },
        { 0xfc00u, 0xff800000u }, { 0x8000u, 0x80000000u }, { 0x3c01u, 0x3f802000u },
    };
    uint32_t i;
    bad = 0;
    for (i = 0; i < PVK_ARRAY_SIZE(to16); i++) {
        uint32_t rte = pvk_spv_f32_to_f16(to16[i].f32, false), rtz = pvk_spv_f32_to_f16(to16[i].f32, true);
        EXPECT(rte == to16[i].rte && rtz == to16[i].rtz, "f32 0x%08x -> f16 0x%04x (RTZ 0x%04x), want 0x%04x (0x%04x)",
               to16[i].f32, rte, rtz, to16[i].rte, to16[i].rtz);
    }
    for (i = 0; i < PVK_ARRAY_SIZE(to32); i++) {
        uint32_t f = pvk_spv_f16_to_f32(to32[i].f16);
        EXPECT(f == to32[i].f32, "f16 0x%04x -> f32 0x%08x, want 0x%08x", to32[i].f16, f, to32[i].f32);
    }
    /* NaNs stay NaNs (quiet), both ways */
    EXPECT((pvk_spv_f32_to_f16(0x7f800001u, false) & 0x7c00u) == 0x7c00u &&
               (pvk_spv_f32_to_f16(0x7f800001u, false) & 0x3ffu) != 0,
           "a NaN converts to 0x%04x", pvk_spv_f32_to_f16(0x7f800001u, false));
    EXPECT(isnan(f32_of(pvk_spv_f16_to_f32(0x7c01u))), "f16 NaN 0x7c01 converts to 0x%08x", pvk_spv_f16_to_f32(0x7c01u));
    CHECK(bad == 0);
}

/* Floating-point and vector OpSpecConstantOp (spv_spec_ops: Select of floats
 * and vectors, FConvert both ways, CompositeExtract, VectorShuffle,
 * LogicalNot, SNegate, IMul, vector IAdd) folded with the defaults and with
 * three specializations (rounding, overflow, denormals). */
static void test_spec_float_ops(void)
{
    struct spec_data {
        uint32_t b;
        float f;
        uint16_t hf, pad;
        int32_t i;
    } data[3] = {
        { 0, 0.0f, 0x3c01u, 0, 5 },     /* F = 1/3 (set below), HF = 1 + 2^-10 */
        { 1, 65520.0f, 0x0001u, 0, -1 }, /* overflows to infinity; HF = 2^-24 */
        { 1, -1e-7f, 0xfc00u, 0, 0 },   /* a binary16 denormal; HF = -infinity */
    };
    VkSpecializationMapEntry entries[4] = {
        { 0, offsetof(struct spec_data, b), 4 },
        { 1, offsetof(struct spec_data, f), 4 },
        { 2, offsetof(struct spec_data, hf), 2 },
        { 3, offsetof(struct spec_data, i), 4 },
    };
    /* float(float16_t(F)) and float(HF) for the defaults and each specialization */
    static const uint32_t backs[4] = { 0x3fc00000u, 0x3eaaa000u, 0x7f800000u, 0xb4000000u };
    static const uint32_t fhs[4] = { 0x40200000u, 0x3f802000u, 0x33800000u, 0xff800000u };
    VkSpecializationInfo info;
    struct pvk_msl_options options;
    uint32_t k, j;

    data[0].f = 1.0f / 3.0f;
    for (k = 0; k < 4; k++) {
        const struct spec_data *d = k ? &data[k - 1] : NULL;
        bool b = d ? d->b != 0 : true;
        float F = d ? d->f : 1.5f, fh = f32_of(fhs[k]), back = f32_of(backs[k]);
        int32_t I = d ? d->i : -7;
        float sel = b ? F : -2.0f;
        float want[12];
        int32_t iwant[4];
        struct pvk_msl_result res;
        struct mt_buffer out;
        struct mt_binding bd;
        id pso;

        want[0] = sel;
        want[1] = b ? 1.0f : F;
        want[2] = b ? 2.0f : F;
        want[3] = b ? 3.0f : F;
        want[4] = back;
        want[5] = fh;
        want[6] = fh;              /* comp.z */
        want[7] = 4.0f;            /* comp.w */
        want[8] = sel;             /* comp.y */
        want[9] = b ? fh : 0.0f;   /* v2.x */
        want[10] = sel;            /* big.w */
        want[11] = b ? 1.0f : 0.0f;
        iwant[0] = -I;
        iwant[1] = I + 1;
        iwant[2] = I * 2 + 1;
        iwant[3] = I;
        memset(&options, 0, sizeof(options));
        if (d) {
            info.mapEntryCount = 4;
            info.pMapEntries = entries;
            info.dataSize = sizeof(*d);
            info.pData = d;
            options.specialization = &info;
        }
        REQUIRE(mt_translate(spv_spec_ops, PVK_ARRAY_SIZE(spv_spec_ops), &options, &res));
        pso = mt_pipeline(&res);
        if (!pso)
            pvk_msl_result_free(&res);
        REQUIRE(pso);
        out = mt_buffer(16 * 4, NULL, 0);
        bd = bind(0, 0, &out);
        CHECK(mt_dispatch(pso, &res, &bd, 1, NULL, 0, 1, 1, 1));
        bad = 0;
        for (j = 0; j < 12; j++) {
            float got = ((const float *)out.data)[j];
            EXPECT(got == want[j] || (isnan(got) && isnan(want[j])), "specialization %u: o[%u] = %a, want %a", k, j,
                   (double)got, (double)want[j]);
        }
        for (j = 0; j < 4; j++) {
            int32_t got = ((const int32_t *)out.data)[12 + j];
            EXPECT(got == iwant[j], "specialization %u: i[%u] = %d, want %d", k, j, got, iwant[j]);
        }
        CHECK(bad == 0);
        mt_buffer_free(&out);
        pvk_release(pso);
        pvk_msl_result_free(&res);
    }
}

/* ==========================================================================
 * Types and built-in functions
 * ========================================================================== */

static void test_int64(void)
{
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[2];
    uint64_t a[64], s = 0x9e3779b97f4a7c15ull, *o;
    uint32_t i;
    id pso;

    MT_BUILD(spv_int64, NULL, res, pso);
    for (i = 0; i < 64; i++) {
        s = s * 6364136223846793005ull + 1442695040888963407ull;
        a[i] = s ^ (s >> 29);
        if (i % 7 == 3)
            a[i] = (uint64_t)-(int64_t)(i * 1000003u); /* some negative values */
    }
    in = mt_buffer(sizeof(a), a, sizeof(a));
    out = mt_buffer(32 * 8 * 8, NULL, 0);
    b[0] = bind(0, 0, &in);
    b[1] = bind(0, 1, &out);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    o = out.data;
    bad = 0;
    for (i = 0; i < 32; i++) {
        uint64_t x = a[2 * i], y = a[2 * i + 1], w[8];
        int64_t sx = (int64_t)x, sy = (int64_t)(y % 1000u) - 500, r;
        uint32_t k;
        if (sy == 0)
            sy = 7;
        r = sx % sy;
        if (r != 0 && ((r < 0) != (sy < 0)))
            r += sy; /* OpSMod */
        w[0] = x * y + 0x123456789ull;
        w[1] = (x >> (y % 64)) ^ (y << (x % 64));
        w[2] = (uint64_t)(sx / sy);
        w[3] = (uint64_t)r;
        w[4] = (uint64_t)(sx >> 3);
        w[5] = (x << 32) | (x >> 32);
        w[6] = (uint64_t)(uint32_t)x + (uint64_t)(int64_t)(int32_t)(uint32_t)y;
        w[7] = (x < y ? 1u : 0u) | (sx < (int64_t)y ? 2u : 0u) | ((uint64_t)(float)(x & 0xffff) << 8);
        for (k = 0; k < 8; k++)
            EXPECT(o[8 * i + k] == w[k], "thread %u value %u: %llx, want %llx", i, k, (unsigned long long)o[8 * i + k],
                   (unsigned long long)w[k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* float -> half, for values a half represents exactly (normal or zero). */
static uint16_t to_half(float f)
{
    uint32_t x;
    memcpy(&x, &f, 4);
    if ((x & 0x7fffffffu) == 0)
        return (uint16_t)((x >> 16) & 0x8000u);
    return (uint16_t)(((x >> 16) & 0x8000u) | ((((x >> 23) & 0xffu) - 112u) << 10) | ((x >> 13) & 0x3ffu));
}

static float from_half(uint16_t h)
{
    return pvk_spv_half_to_float(h);
}

static void test_small_types(void)
{
    static const float add[4] = { 1.0f, 0.5f, -1.0f, 0.25f };
    struct pvk_msl_result res;
    struct mt_buffer h, s, u8, st;
    struct mt_binding b[4];
    uint16_t hv[64], *ho;
    int16_t sv[16], *so;
    uint8_t bv[16], *bo;
    unsigned char sb[32];
    uint32_t i, k;
    id pso;

    MT_BUILD(spv_small, NULL, res, pso);
    for (i = 0; i < 64; i++)
        hv[i] = to_half((float)((int)i - 30) * 0.25f);
    for (i = 0; i < 16; i++) {
        sv[i] = (int16_t)(i * 2731 - 20000);
        bv[i] = (uint8_t)(i * 37);
    }
    memset(sb, 0xcc, sizeof(sb));
    for (k = 0; k < 3; k++)
        memcpy(sb + 2 * k, &(uint16_t){ to_half(1.5f + (float)k) }, 2); /* v3 at 0 */
    memcpy(sb + 6, &(uint16_t){ to_half(10.0f) }, 2);                   /* after at 6 */
    sb[8] = (unsigned char)(int8_t)-7;                                   /* c at 8 */
    memcpy(sb + 10, &(uint16_t){ 1234 }, 2);                            /* us at 10 */
    for (k = 0; k < 3; k++)
        memcpy(sb + 16 + 2 * k, &(uint16_t){ to_half(0.75f * (float)(k + 1)) }, 2); /* arr[0] at 16 */
    h = mt_buffer(sizeof(hv), hv, sizeof(hv));
    s = mt_buffer(sizeof(sv), sv, sizeof(sv));
    u8 = mt_buffer(sizeof(bv), bv, sizeof(bv));
    st = mt_buffer(sizeof(sb), sb, sizeof(sb));
    b[0] = bind(0, 0, &h);
    b[1] = bind(0, 1, &s);
    b[2] = bind(0, 2, &u8);
    b[3] = bind(0, 3, &st);
    CHECK(mt_dispatch(pso, &res, b, 4, NULL, 0, 1, 1, 1));
    ho = h.data;
    so = s.data;
    bo = u8.data;
    bad = 0;
    for (i = 0; i < 64; i++) {
        float want = from_half(hv[i]) * 2.0f + add[i % 4];
        EXPECT(from_half(ho[i]) == want, "h[%u] = %g, want %g", i, from_half(ho[i]), want);
    }
    for (i = 0; i < 16; i++) {
        EXPECT(so[i] == (int16_t)(sv[i] * 3 - 7), "s[%u] = %d", i, so[i]);
        EXPECT(bo[i] == (uint8_t)(bv[i] + 200), "b[%u] = %u", i, bo[i]);
    }
    {
        const unsigned char *o = st.data;
        uint16_t x;
        for (k = 0; k < 3; k++) {
            memcpy(&x, o + 2 * k, 2);
            EXPECT(from_half(x) == 3.5f - (float)k, "st.v3[%u] = %g", k, from_half(x));
            memcpy(&x, o + 24 + 2 * k, 2);
            EXPECT(from_half(x) == 0.75f * (float)(k + 1), "st.arr[1][%u] = %g", k, from_half(x));
        }
        memcpy(&x, o + 6, 2);
        EXPECT(from_half(x) == 11.0f, "st.after = %g", from_half(x));
        EXPECT((int8_t)o[8] == 7, "st.c = %d", (int8_t)o[8]);
        EXPECT(o[9] == 0xcc && o[14] == 0xcc && o[15] == 0xcc, "padding written");
        memcpy(&x, o + 10, 2);
        EXPECT(x == 2468, "st.us = %u", x);
    }
    CHECK(bad == 0);
    mt_buffer_free(&h);
    mt_buffer_free(&s);
    mt_buffer_free(&u8);
    mt_buffer_free(&st);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static double dsign(double x)
{
    return x > 0 ? 1.0 : x < 0 ? -1.0 : 0.0;
}

/* GLSL.std.450 against libm. */
static void test_glsl_std450(void)
{
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[2];
    float x[8][4];
    uint32_t i, k;
    id pso;

    MT_BUILD(spv_glsl, NULL, res, pso);
    for (i = 0; i < 8; i++) {
        x[i][0] = (float)i * 0.3f - 1.1f;
        x[i][1] = 1.7f - (float)i * 0.45f;
        x[i][2] = (float)i * 0.23f - 0.8f;
        x[i][3] = 0.6f + (float)i * 0.1f;
    }
    in = mt_buffer(sizeof(x), x, sizeof(x));
    out = mt_buffer(8 * 48 * 4, NULL, 0);
    b[0] = bind(0, 0, &in);
    b[1] = bind(0, 1, &out);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 8; i++) {
        double a = x[i][0], bb = x[i][1], c = x[i][2], v[4] = { x[i][0], x[i][1], x[i][2], x[i][3] };
        double want[48], ip, fr, len, nv[3], nn[3] = { 1, 2, 3 }, d, k2, ni[3], hv;
        int e;
        const float *o = (const float *)out.data + 48 * i;
        k = 0;
        want[k++] = sin(a);
        want[k++] = cos(a);
        want[k++] = tan(a);
        want[k++] = asin(c);
        want[k++] = acos(c);
        want[k++] = atan2(bb, a);
        want[k++] = atan(a);
        want[k++] = sinh(a);
        want[k++] = cosh(a);
        want[k++] = tanh(a);
        want[k++] = asinh(a);
        want[k++] = acosh(fabs(a) + 1.0);
        want[k++] = atanh(c);
        want[k++] = exp(a);
        want[k++] = log(fabs(bb) + 0.5);
        want[k++] = exp2(bb);
        want[k++] = log2(fabs(a) + 0.5);
        want[k++] = pow(fabs(a) + 0.1, bb);
        want[k++] = sqrt(fabs(bb));
        want[k++] = 1.0 / sqrt(fabs(bb) + 0.25);
        want[k++] = floor(bb);
        want[k++] = ceil(bb);
        want[k++] = bb - floor(bb);
        want[k++] = bb - 0.75 * floor(bb / 0.75);
        want[k++] = -bb - 0.75 * floor(-bb / 0.75);
        want[k++] = trunc(bb);
        want[k++] = round((float)bb * 2.0f);
        want[k++] = rint(2.5 + i);
        want[k++] = dsign(c);
        want[k++] = bb < -0.5 ? -0.5 : bb > 0.5 ? 0.5 : bb;
        want[k++] = a + (bb - a) * 0.25;
        want[k++] = c < 0.0 ? 0.0 : 1.0;
        hv = (c + 1.0) / 2.0;
        want[k++] = hv * hv * (3.0 - 2.0 * hv);
        want[k++] = a * bb + c;
        fr = frexp((double)((float)bb * 100.0f), &e);
        want[k++] = fr;
        want[k++] = e;
        want[k++] = ldexp(a, (int)i - 3);
        want[k++] = modf((double)((float)bb * 3.0f), &ip);
        want[k++] = ip;
        want[k++] = bb * 90.0 * 3.14159265358979323846 / 180.0;
        want[k++] = a * 180.0 / 3.14159265358979323846;
        want[k++] = sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
        want[k++] = sqrt((v[0] - v[2]) * (v[0] - v[2]) + (v[1] - v[3]) * (v[1] - v[3]));
        want[k++] = v[3] / sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2] + v[3] * v[3]);
        len = sqrt(14.0);
        for (e = 0; e < 3; e++)
            nn[e] /= len;
        d = nn[0] * v[0] + nn[1] * v[1] + nn[2] * v[2];
        want[k++] = v[1] - 2.0 * d * nn[1]; /* reflect(v, n).y */
        len = sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
        for (e = 0; e < 3; e++)
            ni[e] = v[e] / len;
        d = ni[1]; /* dot(N = (0,1,0), I) */
        k2 = 1.0 - 0.75 * 0.75 * (1.0 - d * d);
        nv[2] = k2 < 0 ? 0.0 : 0.75 * ni[2] - (0.75 * d + sqrt(k2)) * 0.0;
        want[k++] = nv[2]; /* refract(I, (0,1,0), 0.75).z */
        want[k++] = (v[2] * v[0] + v[3] * v[1]) < 0 ? 1.0 : -1.0; /* faceforward((1,2), I, Nref).x */
        want[k++] = (a < bb ? a : bb) + (a > c ? a : c);
        for (k = 0; k < 48; k++)
            EXPECT(mt_near(o[k], want[k], 2e-5), "thread %u function %u: %.9g, want %.9g", i, k, o[k], want[k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* Arrays and structs as values: constant tables, array/struct returns,
 * copies, dynamic indexing of local arrays. */
static void check_values(const uint32_t *words, size_t count)
{
    static const float lut[5] = { 1, 2, 4, 8, 16 };
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    uint32_t i;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    out = mt_buffer(16 * 24, NULL, 0);
    b = bind(0, 0, &out);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 16; i++) { /* Item: p 0, id 8, w 12; 24 bytes */
        const char *it = (const char *)out.data + 24 * i;
        float fi = (float)i;
        EXPECT(get_f32(it, 0) == 4 * fi + 8.5f && get_f32(it, 4) == -fi, "items[%u].p = %g %g", i, get_f32(it, 0),
               get_f32(it, 4));
        EXPECT(get_u32(it, 8) == i + (i & 1 ? 100u : 0u), "items[%u].id = %u", i, get_u32(it, 8));
        EXPECT(get_f32(it, 12) == 0.5f && get_f32(it, 16) == lut[i % 5] && get_f32(it, 20) == 2.5f,
               "items[%u].w = %g %g %g", i, get_f32(it, 12), get_f32(it, 16), get_f32(it, 20));
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_values(void)
{
    check_values(spv_values, PVK_ARRAY_SIZE(spv_values));
}

static void test_values_opt(void)
{
    check_values(spv_values_opt, PVK_ARRAY_SIZE(spv_values_opt));
}

/* Boolean vectors, vector selects, dynamic vector and matrix indexing,
 * matrix arithmetic, integer vector shifts, private globals passed to a
 * helper, nested struct/array copies, isnan/isinf. */
static void check_vecops(const uint32_t *words, size_t count)
{
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    uint32_t t, k, c, r;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    out = mt_buffer(4 * 12 * 16, NULL, 0);
    b = bind(0, 0, &out);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    bad = 0;
    for (t = 0; t < 4; t++) {
        float fi = (float)t, a[4], bv[4], v[4], m[3][3], m2, w[12][4];
        int32_t i = (int32_t)t, iv[3];
        uint32_t uv[3] = { t, 7, 0xf0 };
        bool lt[4], ge[4];
        a[0] = fi, a[1] = 2, a[2] = -fi, a[3] = 0.5f * fi;
        bv[0] = 1, bv[1] = fi, bv[2] = 0, bv[3] = 1.5f;
        for (k = 0; k < 4; k++) {
            lt[k] = a[k] < bv[k];
            ge[k] = a[k] >= bv[k];
            w[0][k] = (float)lt[k] + 2.0f * (float)ge[k];
            w[2][k] = lt[k] ? bv[k] : a[k];
            w[3][k] = (t & 1) ? a[k] : bv[k];
            v[k] = a[k];
        }
        w[1][0] = (float)(lt[0] || lt[1] || lt[2] || lt[3]);
        w[1][1] = (float)(ge[0] && ge[1] && ge[2] && ge[3]);
        w[1][2] = (float)(!ge[0] || !ge[1] || !ge[2] || !ge[3]);
        w[1][3] = 1;
        v[2] = 7;
        v[0] = 8;
        v[t % 4] = 100;
        memcpy(w[4], v, sizeof(v));
        w[5][0] = a[(t + 1) % 4];
        w[5][1] = 0.5f, w[5][2] = 1, w[5][3] = 1.5f;
        for (c = 0; c < 3; c++)
            for (r = 0; r < 3; r++)
                m[c][r] = c == r ? 1.0f : 0.0f;
        m[t % 3][0] = fi, m[t % 3][1] = fi + 1, m[t % 3][2] = fi + 2;
        m[(t + 1) % 3][t % 3] = -5;
        for (k = 0; k < 3; k++)
            w[6][k] = m[0][k];
        w[6][3] = (float)(1 + i);
        for (k = 0; k < 4; k++) { /* matrixCompMult(m, 3m - 0.5I): m3[1].xyz, m3[2].z */
            c = k < 3 ? 1 : 2;
            r = k < 3 ? k : 2;
            m2 = 3.0f * m[c][r] - (c == r ? 0.5f : 0.0f);
            w[7][k] = m[c][r] * m2;
        }
        iv[0] = 3 * i, iv[1] = -3 * i, iv[2] = 9;
        for (k = 0; k < 3; k++) {
            w[8][k] = (float)iv[k];
            w[9][k] = (float)((uv[k] << (k + 1)) | ((uint32_t)iv[k] >> 1));
        }
        w[8][3] = 1;
        w[9][3] = 0;
        w[10][0] = 42, w[10][1] = -(float)((t + 1) % 3), w[10][2] = fi, w[10][3] = 3;
        w[11][0] = 1, w[11][1] = 0, w[11][2] = 1, w[11][3] = 0;
        for (k = 0; k < 48; k++) {
            float got = ((const float *)out.data)[48 * t + k];
            EXPECT(got == w[k / 4][k % 4], "thread %u f[%u].%c = %g, want %g", t, k / 4, "xyzw"[k % 4], got, w[k / 4][k % 4]);
        }
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_vecops(void)
{
    check_vecops(spv_vecops, PVK_ARRAY_SIZE(spv_vecops));
}

static void test_vecops_opt(void)
{
    check_vecops(spv_vecops_opt, PVK_ARRAY_SIZE(spv_vecops_opt));
}

static int find_msb_s(int32_t v)
{
    uint32_t u = (uint32_t)(v < 0 ? ~v : v);
    int n = -1;
    while (u) {
        n++;
        u >>= 1;
    }
    return n;
}

static int find_msb_u(uint32_t u)
{
    int n = -1;
    while (u) {
        n++;
        u >>= 1;
    }
    return n;
}

static int find_lsb(uint32_t u)
{
    int n = 0;
    if (!u)
        return -1;
    while (!(u & 1u)) {
        n++;
        u >>= 1;
    }
    return n;
}

static int popcount32(uint32_t u)
{
    int n = 0;
    for (; u; u &= u - 1)
        n++;
    return n;
}

static void test_intops(void)
{
    static const int32_t pairs[16][2] = {
        { 100, 7 }, { -100, 7 }, { 100, -7 }, { -100, -7 }, { 12345678, 3 }, { -1, 5 }, { 0x7ffffff0, 0x13 },
        { -2147483600, 77 }, { 5, 100000 }, { 0x5a5a5a5a, 0x0f0f0f0f }, { -0x1234567, 0x89ab }, { 1, -1 },
        { 0, 9 }, { 256, 256 }, { -65536, 3 }, { 0x40000000, -2 },
    };
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[2];
    uint32_t i, k;
    id pso;

    MT_BUILD(spv_intops, NULL, res, pso);
    in = mt_buffer(sizeof(pairs), pairs, sizeof(pairs));
    out = mt_buffer(16 * 24 * 4, NULL, 0);
    b[0] = bind(0, 0, &in);
    b[1] = bind(0, 1, &out);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 16; i++) {
        int32_t a = pairs[i][0], bv = pairs[i][1], w[24];
        uint32_t ua = (uint32_t)a, ub = (uint32_t)bv, mask;
        uint64_t up = (uint64_t)ua * ub;
        int64_t sp = (int64_t)a * bv;
        k = 0;
        w[k++] = a / bv;
        w[k++] = smod32(a, bv);
        w[k++] = (int32_t)(ua / ub);
        w[k++] = (int32_t)(ua % ub);
        w[k++] = a >> 3;
        w[k++] = (int32_t)(ua >> 3);
        w[k++] = (int32_t)(ua << (bv & 7));
        w[k++] = (a & bv) | (a ^ ~bv);
        w[k++] = (int32_t)(0u - ua);
        w[k++] = (a < 0 ? -a : a) + (bv > 0) - (bv < 0);
        w[k++] = (uint32_t)(a < bv ? a : bv) * 3u + (ua > ub ? ua : ub) > 5u ? 1 : 0;
        w[k++] = a < -5 ? -5 : a > 5 ? 5 : a;
        w[k++] = (int32_t)(ua + ub + (ua + ub < ua ? 1u : 0u));
        w[k++] = (int32_t)(ua - ub + (ua < ub ? 1u : 0u));
        w[k++] = (int32_t)((uint32_t)(up >> 32) ^ (uint32_t)up);
        w[k++] = (int32_t)((uint32_t)((uint64_t)sp >> 32) + (uint32_t)(uint64_t)sp);
        w[k++] = (int32_t)(((ua >> 3) & 0x1ffu) ^ 0x100u) - 0x100; /* signed 9-bit field */
        w[k++] = (int32_t)((ua >> 5) & 0xfffu);
        mask = 0xffu << 4;
        w[k++] = (int32_t)((ua & ~mask) | ((ub << 4) & mask));
        {
            uint32_t r = 0, t = ua, n;
            for (n = 0; n < 32; n++, t >>= 1)
                r = (r << 1) | (t & 1u);
            w[k++] = (int32_t)r;
        }
        w[k++] = popcount32(ua) + popcount32(ub);
        w[k++] = find_lsb(ua) * 100 + find_lsb(ub);
        w[k++] = find_msb_s(a) * 100 + find_msb_u(ub);
        w[k++] = (int32_t)((float)a * 0.5f) + (int32_t)(uint32_t)fabsf((float)bv);
        for (k = 0; k < 24; k++)
            EXPECT(((int32_t *)out.data)[24 * i + k] == w[k], "pair %u op %u: %d, want %d", i, k,
                   ((int32_t *)out.data)[24 * i + k], w[k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* Three descriptor sets, a descriptor array with a runtime-array length
 * read from the 16-byte buffer descriptors, the default layout and a given
 * one (unused bindings, a dynamic uniform buffer, a padded stride). */
static void test_sets(void)
{
    static const struct pvk_msl_binding set0[] = { { 0, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, 0, 16, false } };
    static const struct pvk_msl_binding set1[] = { { 0, VK_DESCRIPTOR_TYPE_SAMPLER, 2, 0, 8, false },
                                                   { 1, VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC, 1, 16, 16, false } };
    static const struct pvk_msl_binding set2[] = { { 1, VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 1, 0, 16, false },
                                                   { 3, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 4, 32, 48, false } };
    static const struct pvk_msl_set_layout layouts[3] = { { set0, 1 }, { set1, 2 }, { set2, 2 } };
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer a, u, v[3];
    struct mt_binding b[5];
    uint32_t i, k, pass, data[3][60], kval = 5;
    id pso;

    for (pass = 0; pass < 2; pass++) {
        memset(&options, 0, sizeof(options));
        if (pass) {
            options.set_layouts = layouts;
            options.set_layout_count = 3;
        }
        MT_BUILD(spv_sets, &options, res, pso);
        CHECK(res.set_mask == 7 && res.resource_count == 3);
        CHECK(res.resources[0].set == 0 && res.resources[0].binding == 0 && res.resources[0].offset == 0);
        CHECK(res.resources[1].set == 1 && res.resources[1].binding == 1 &&
              res.resources[1].offset == (pass ? 16u : 0u) &&
              res.resources[1].type == (pass ? VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC : VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER));
        CHECK(res.resources[2].set == 2 && res.resources[2].binding == 3 && res.resources[2].count == (pass ? 4u : 3u) &&
              res.resources[2].offset == (pass ? 32u : 0u) && res.resources[2].stride == (pass ? 48u : 16u) &&
              !res.resources[2].writable && !res.resources[2].variable_count);
        a = mt_buffer(32 * 4, NULL, 0);
        u = mt_buffer(16, &kval, 4);
        for (k = 0; k < 3; k++) {
            for (i = 0; i < 60; i++)
                data[k][i] = 1000u * k + i;
            v[k] = mt_buffer(sizeof(data[k]), data[k], sizeof(data[k]));
            b[2 + k] = bind(2, 3, &v[k]);
            b[2 + k].index = k;
            b[2 + k].range = (32 + 4 * k) * 4; /* lengths 32, 36, 40 */
        }
        b[0] = bind(0, 0, &a);
        b[1] = bind(1, 1, &u);
        CHECK(mt_dispatch(pso, &res, b, 5, NULL, 0, 1, 1, 1));
        bad = 0;
        for (i = 0; i < 32; i++) {
            uint32_t want = data[0][i] + data[1][i] * kval + data[i % 3][0] + 40;
            EXPECT(((uint32_t *)a.data)[i] == want, "a[%u] = %u, want %u", i, ((uint32_t *)a.data)[i], want);
        }
        CHECK(bad == 0);
        mt_buffer_free(&a);
        mt_buffer_free(&u);
        for (k = 0; k < 3; k++)
            mt_buffer_free(&v[k]);
        pvk_release(pso);
        pvk_msl_result_free(&res);
    }
}

/* spv_bda over a list of 8 nodes (std430 Node: vec4 at 0, next at 16, tag at
 * 24; 32 bytes), 32 threads. */
static void run_bda(const uint32_t *words, size_t count)
{
    enum { NODES = 8, N = 32 };
    struct pvk_msl_result res;
    struct mt_buffer nodes, out, counter, links;
    struct mt_binding b[4];
    unsigned char push[48];
    uint32_t i, k;
    id pso;

    REQUIRE(mt_translate(words, count, NULL, &res));
    CHECK(res.has_push_constants && res.push_constant_offset == 0 && res.push_constant_size == 36);
    CHECK(res.set_mask == 0 && res.resource_count == 0);
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    nodes = mt_buffer(32 * NODES, NULL, 0);
    for (k = 0; k < NODES; k++) {
        unsigned char *node = (unsigned char *)nodes.data + 32 * k;
        uint64_t next = k + 1 < NODES ? nodes.address + 32 * (k + 1) : 0;
        put_f32(node, 0, (float)(k + 1));
        put_f32(node, 4, 10.0f);
        put_f32(node, 8, 20.0f);
        put_f32(node, 12, 30.0f);
        memcpy(node + 16, &next, 8);
        put_u32(node, 24, k + 2);
    }
    out = mt_buffer(4 * 3 * N, NULL, 0);
    counter = mt_buffer(16, NULL, 0);
    links = mt_buffer(8 * N, NULL, 0);
    memset(push, 0, sizeof(push));
    memcpy(push, &nodes.address, 8);       /* head */
    memcpy(push + 8, &out.address, 8);     /* out_addr */
    memcpy(push + 16, &counter.address, 8); /* counter_addr: uvec2, low word first */
    memcpy(push + 24, &links.address, 8);  /* links */
    put_u32(push, 32, N);
    /* Buffers reached only through addresses: set 7 is not the shader's, so
     * the bindings only make them resident. */
    b[0] = bind(7, 0, &nodes);
    b[1] = bind(7, 1, &out);
    b[2] = bind(7, 2, &counter);
    b[3] = bind(7, 3, &links);
    CHECK(mt_dispatch(pso, &res, b, 4, push, sizeof(push), 1, 1, 1));
    bad = 0;
    for (i = 0; i < N; i++) {
        uint32_t want = 0, steps = i + 1 < NODES ? i + 1 : NODES;
        uint64_t link;
        for (k = 0; k < steps; k++)
            want += (k + 1) * (k + 2);
        EXPECT(get_u32(out.data, 4 * i) == want, "list sum %u = %u, want %u", i, get_u32(out.data, 4 * i), want);
        EXPECT(get_u32(out.data, 4 * (N + i)) == get_u32(nodes.data, 4 * (i % 4)), "word %u of node 0: %08x", i % 4,
               get_u32(out.data, 4 * (N + i)));
        EXPECT(get_u32(out.data, 4 * (2 * N + i)) == get_u32(nodes.data, 4 * (i % 4) + 4), "word %u of node 0: %08x",
               i % 4 + 1, get_u32(out.data, 4 * (2 * N + i)));
        memcpy(&link, (char *)links.data + 8 * i, 8);
        EXPECT(link == ((i & 1) ? nodes.address : nodes.address + 32), "stored pointer %u = %llx", i,
               (unsigned long long)link);
    }
    EXPECT(get_u32(counter.data, 0) == N, "counter = %u", get_u32(counter.data, 0));
    CHECK(bad == 0);
    mt_buffer_free(&nodes);
    mt_buffer_free(&out);
    mt_buffer_free(&counter);
    mt_buffer_free(&links);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_bda(void)
{
    run_bda(spv_bda, PVK_ARRAY_SIZE(spv_bda));
}

static void test_bda_opt(void)
{
    run_bda(spv_bda_opt, PVK_ARRAY_SIZE(spv_bda_opt));
}

/* Base workgroup (1, 2, 0), 2 x 1 x 1 workgroups of 4 x 2: invocations
 * (4..11, 4..5) write, the rest of the 16 x 8 grid stays zero. */
static void test_dispatch_base(void)
{
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    unsigned char push[32];
    uint32_t x, y;
    id pso;

    REQUIRE(mt_translate(spv_dispatch_base, PVK_ARRAY_SIZE(spv_dispatch_base), NULL, &res));
    CHECK(!res.dispatch_base);
    pvk_msl_result_free(&res);
    memset(&options, 0, sizeof(options));
    options.dispatch_base = true;
    options.dispatch_base_offset = 70000;
    CHECK(pvk_spirv_to_msl(spv_dispatch_base, PVK_ARRAY_SIZE(spv_dispatch_base), NULL, &options, &res) ==
              VK_ERROR_INITIALIZATION_FAILED &&
          strstr(res.error, "too large"));
    pvk_msl_result_free(&res);
    options.dispatch_base_offset = 4; /* rounded up to 16 */
    MT_BUILD(spv_dispatch_base, &options, res, pso);
    CHECK(res.dispatch_base && res.dispatch_base_offset == 16 && res.has_push_constants);

    out = mt_buffer(16 * 16 * 8, NULL, 0);
    memset(push, 0, sizeof(push));
    put_u32(push, 0, 16); /* width */
    put_u32(push, 16, 1);
    put_u32(push, 20, 2);
    b = bind(0, 0, &out);
    CHECK(mt_dispatch(pso, &res, &b, 1, push, sizeof(push), 2, 1, 1));
    bad = 0;
    for (y = 0; y < 8; y++) {
        for (x = 0; x < 16; x++) {
            const uint32_t *o = (const uint32_t *)out.data + 4 * (16 * y + x);
            bool in = x >= 4 && x < 12 && y >= 4 && y < 6;
            uint32_t w0 = in ? x / 4 : 0, w1 = in ? y / 2 : 0, w2 = in ? (y % 2) * 4 + x % 4 : 0, w3 = in ? 2 : 0;
            EXPECT(o[0] == w0 && o[1] == w1 && o[2] == w2 && o[3] == w3, "(%u, %u) = %u %u %u %u, want %u %u %u %u", x,
                   y, o[0], o[1], o[2], o[3], w0, w1, w2, w3);
        }
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ==========================================================================
 * Rejection and robustness
 * ========================================================================== */

static bool fails_with(const uint32_t *words, size_t count, const char *needle)
{
    struct pvk_msl_result res;
    VkResult r = pvk_spirv_to_msl(words, count, NULL, NULL, &res);
    bool ok = r == VK_ERROR_INITIALIZATION_FAILED && res.msl == NULL && strstr(res.error, needle) != NULL;
    if (!ok)
        fprintf(stderr, "  result %d, error \"%s\", expected \"%s\"\n", (int)r, res.error, needle);
    pvk_msl_result_free(&res);
    return ok;
}

static void test_reject_double(void)
{
    CHECK(fails_with(spv_f64, PVK_ARRAY_SIZE(spv_f64), "double"));
}

static void test_reject_malformed(void)
{
    uint32_t w[PVK_ARRAY_SIZE(spv_copy)];
    struct pvk_msl_options options;
    struct pvk_msl_result res;

    CHECK(fails_with(NULL, 0, "too short"));
    CHECK(fails_with(spv_copy, 4, "too short"));
    memcpy(w, spv_copy, sizeof(w));
    w[0] = 0x12345678u;
    CHECK(fails_with(w, PVK_ARRAY_SIZE(w), "magic"));
    w[0] = 0x03022307u;
    CHECK(fails_with(w, PVK_ARRAY_SIZE(w), "byte-swapped"));
    memcpy(w, spv_copy, sizeof(w));
    w[1] = 0x00020000u;
    CHECK(fails_with(w, PVK_ARRAY_SIZE(w), "version"));
    memcpy(w, spv_copy, sizeof(w));
    w[3] = 0xffffffffu;
    CHECK(fails_with(w, PVK_ARRAY_SIZE(w), "bound"));
    memcpy(w, spv_copy, sizeof(w));
    w[5] = 0xffff0011u; /* OpCapability claiming 65535 words */
    CHECK(fails_with(w, PVK_ARRAY_SIZE(w), "malformed"));
    CHECK(fails_with(spv_copy, PVK_ARRAY_SIZE(spv_copy) - 1, "")); /* cut inside OpFunctionEnd */
    CHECK(pvk_spirv_to_msl(spv_copy, PVK_ARRAY_SIZE(spv_copy), "nope", NULL, &res) == VK_ERROR_INITIALIZATION_FAILED &&
          strstr(res.error, "not found"));
    pvk_msl_result_free(&res);
    CHECK(pvk_spirv_to_msl(spv_copy, PVK_ARRAY_SIZE(spv_copy), "main", NULL, &res) == VK_SUCCESS);
    pvk_msl_result_free(&res);

    memset(&options, 0, sizeof(options)); /* push constants must fit Metal and miss the sets */
    options.push_constant_buffer = 31;
    CHECK(pvk_spirv_to_msl(spv_saxpy, PVK_ARRAY_SIZE(spv_saxpy), NULL, &options, &res) == VK_ERROR_INITIALIZATION_FAILED &&
          strstr(res.error, "out of range"));
    pvk_msl_result_free(&res);
    options.push_constant_buffer = 0;
    options.dispatch_base = true;
    options.push_constant_buffer = 2;
    CHECK(pvk_spirv_to_msl(spv_sets, PVK_ARRAY_SIZE(spv_sets), NULL, &options, &res) == VK_ERROR_INITIALIZATION_FAILED &&
          strstr(res.error, "also descriptor set"));
    pvk_msl_result_free(&res);
}

static uint32_t fuzz_state = 0x2545f491u;
static uint32_t fuzz_next(void)
{
    fuzz_state ^= fuzz_state << 13;
    fuzz_state ^= fuzz_state >> 17;
    fuzz_state ^= fuzz_state << 5;
    return fuzz_state;
}

/* Every truncation and many random corruptions of real modules: the
 * translator must fail cleanly or succeed, never crash (ASan/UBSan run
 * this). */
static void test_corrupted_modules(void)
{
    static const struct { const uint32_t *words; size_t count; } mods[] = {
        { spv_copy, PVK_ARRAY_SIZE(spv_copy) },       { spv_switch_opt, PVK_ARRAY_SIZE(spv_switch_opt) },
        { spv_std140, PVK_ARRAY_SIZE(spv_std140) },   { spv_spec, PVK_ARRAY_SIZE(spv_spec) },
        { spv_funcs, PVK_ARRAY_SIZE(spv_funcs) },     { spv_atomics, PVK_ARRAY_SIZE(spv_atomics) },
        { spv_values_opt, PVK_ARRAY_SIZE(spv_values_opt) }, { spv_sets, PVK_ARRAY_SIZE(spv_sets) },
        { spv_bda, PVK_ARRAY_SIZE(spv_bda) },         { spv_bda_opt, PVK_ARRAY_SIZE(spv_bda_opt) },
        { spv_sample, PVK_ARRAY_SIZE(spv_sample) },   { spv_gather_opt, PVK_ARRAY_SIZE(spv_gather_opt) },
        { spv_depth, PVK_ARRAY_SIZE(spv_depth) },     { spv_storage_opt, PVK_ARRAY_SIZE(spv_storage_opt) },
        { spv_atomics_img, PVK_ARRAY_SIZE(spv_atomics_img) }, { spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays) },
        { spv_inline_block, PVK_ARRAY_SIZE(spv_inline_block) }, { spv_oned, PVK_ARRAY_SIZE(spv_oned) },
    };
    uint32_t m, iter, k, *w, ok = 0;
    size_t len;

    for (m = 0; m < PVK_ARRAY_SIZE(mods); m++) {
        size_t n = mods[m].count;
        w = malloc(n * sizeof(uint32_t));
        REQUIRE(w);
        for (len = 0; len < n; len++) {
            struct pvk_msl_result res;
            memcpy(w, mods[m].words, len * sizeof(uint32_t));
            if (pvk_spirv_to_msl(w, len, NULL, NULL, &res) == VK_SUCCESS)
                ok++;
            else
                CHECK(res.msl == NULL && res.error[0]);
            pvk_msl_result_free(&res);
        }
        for (iter = 0; iter < 1500; iter++) {
            struct pvk_msl_result res;
            uint32_t edits = 1 + fuzz_next() % 4;
            memcpy(w, mods[m].words, n * sizeof(uint32_t));
            for (k = 0; k < edits; k++) {
                size_t pos = 5 + fuzz_next() % (n - 5);
                switch (fuzz_next() % 5) {
                case 0: w[pos] ^= 1u << (fuzz_next() % 32); break;        /* bit flip */
                case 1: w[pos] = 1 + fuzz_next() % mods[m].words[3]; break; /* another id */
                case 2: w[pos] = fuzz_next(); break;                      /* garbage */
                case 3: w[pos] = (w[pos] & 0xffff0000u) | (fuzz_next() % 400); break; /* opcode */
                default: w[pos] = (w[pos] & 0xffffu) | ((fuzz_next() % 12) << 16); break; /* length */
                }
            }
            if (pvk_spirv_to_msl(w, n, NULL, NULL, &res) == VK_SUCCESS)
                ok += res.msl != NULL;
            else
                CHECK(res.msl == NULL && res.error[0]);
            pvk_msl_result_free(&res);
        }
        free(w);
    }
    CHECK(ok > 0); /* some corruptions are harmless (names, debug info) */
}

/* Random set layouts for shaders with many descriptor kinds: translation
 * succeeds or fails cleanly, and every layout it accepts gives MSL that Metal
 * compiles (checked for the first few of each shader). */
static void test_random_layouts(void)
{
    static const VkDescriptorType types[] = {
        VK_DESCRIPTOR_TYPE_SAMPLER, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE,
        VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER, VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER,
        VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC,
        VK_DESCRIPTOR_TYPE_STORAGE_BUFFER_DYNAMIC, VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT,
        VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK, VK_DESCRIPTOR_TYPE_MUTABLE_EXT, (VkDescriptorType)12345,
    };
    static const struct { const uint32_t *words; size_t count; } mods[] = {
        { spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays) }, { spv_inline_block, PVK_ARRAY_SIZE(spv_inline_block) },
        { spv_sample, PVK_ARRAY_SIZE(spv_sample) },         { spv_storage_opt, PVK_ARRAY_SIZE(spv_storage_opt) },
    };
    uint32_t m, iter, k, accepted = 0;
    for (m = 0; m < PVK_ARRAY_SIZE(mods); m++) {
        struct pvk_msl_result res;
        uint32_t compiled = 0;
        REQUIRE(mt_translate(mods[m].words, mods[m].count, NULL, &res)); /* start from the default layout */
        for (iter = 0; iter < 3000; iter++) {
            struct pvk_msl_binding sets[2][12];
            struct pvk_msl_set_layout sl[2];
            struct pvk_msl_options options;
            struct pvk_msl_result r;
            uint32_t n[2] = { 0, 0 }, off[2] = { 0, 0 };
            for (k = 0; k < res.resource_count && k < 24; k++) {
                const struct pvk_msl_resource *d = &res.resources[k];
                struct pvk_msl_binding *b;
                uint32_t set = d->set & 1, roll = fuzz_next();
                if (n[set] == 12 || roll % 23 == 0)
                    continue; /* sometimes missing */
                b = &sets[set][n[set]++];
                b->binding = d->binding;
                b->type = roll % 5 ? d->type : types[fuzz_next() % PVK_ARRAY_SIZE(types)];
                b->count = roll % 7 ? (d->count ? d->count + fuzz_next() % 3 : 1 + fuzz_next() % 6) : fuzz_next() % 4;
                if (b->type == VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK)
                    b->count = 16 * (1 + fuzz_next() % 4);
                b->stride = roll % 3 ? d->stride + 8 * (fuzz_next() % 3) : fuzz_next() % 40;
                b->variable_count = d->variable_count || fuzz_next() % 17 == 0;
                off[set] += roll % 11 ? 16 * (fuzz_next() % 3) : fuzz_next() % 24;
                b->offset = off[set];
                off[set] += b->type == VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK ? b->count : b->stride * b->count;
                if (fuzz_next() % 29 == 0)
                    b->offset = fuzz_next() % 300;
            }
            sl[0].bindings = sets[0];
            sl[0].binding_count = n[0];
            sl[1].bindings = sets[1];
            sl[1].binding_count = n[1];
            memset(&options, 0, sizeof(options));
            options.set_layouts = sl;
            options.set_layout_count = 1 + (res.set_mask >> 1 & 1);
            options.image_1d_as_2d = fuzz_next() & 1;
            if (pvk_spirv_to_msl(mods[m].words, mods[m].count, NULL, &options, &r) == VK_SUCCESS) {
                accepted++;
                CHECK(r.msl != NULL);
                if (compiled < 6) {
                    id pso = mt_pipeline(&r);
                    CHECK(pso != NULL);
                    pvk_release(pso);
                    compiled++;
                }
            } else {
                CHECK(r.msl == NULL && r.error[0]);
            }
            pvk_msl_result_free(&r);
        }
        pvk_msl_result_free(&res);
    }
    CHECK(accepted > 0);
}

static void test_deterministic(void)
{
    struct pvk_msl_result a, b;
    REQUIRE(mt_translate(spv_std140_opt, PVK_ARRAY_SIZE(spv_std140_opt), NULL, &a));
    REQUIRE(mt_translate(spv_std140_opt, PVK_ARRAY_SIZE(spv_std140_opt), NULL, &b));
    CHECK(a.msl_length == b.msl_length && strcmp(a.msl, b.msl) == 0);
    pvk_msl_result_free(&a);
    pvk_msl_result_free(&b);
}

/* ==========================================================================
 * Images, samplers and descriptor sets
 *
 * Textures are created and filled directly with Metal; the CPU references
 * follow the Vulkan spec's texel selection (nearest/linear, LOD, offsets,
 * array layers, cube faces, depth comparison, gather footprints).
 * ========================================================================== */

static const struct mt_sampler_desc smp_nearest = { PVK_MTLSamplerMinMagFilterNearest, 1, PVK_MTLSamplerAddressModeClampToEdge,
                                                    false, 0 };
static const struct mt_sampler_desc smp_linear = { PVK_MTLSamplerMinMagFilterLinear, 2, PVK_MTLSamplerAddressModeClampToEdge,
                                                   false, 0 };

static struct mt_binding bind_tex(uint32_t set, uint32_t binding, uint32_t index, id texture, id sampler)
{
    struct mt_binding b;
    memset(&b, 0, sizeof(b));
    b.set = set;
    b.binding = binding;
    b.index = index;
    b.texture = texture;
    b.sampler = sampler;
    return b;
}

static bool near4(const float *got, const float *want, float tol)
{
    int k;
    for (k = 0; k < 4; k++)
        if (!(fabsf(got[k] - want[k]) <= tol))
            return false;
    return true;
}

/* A 4-component mismatch: the label (printf), then both vectors. */
static void expect4(const float *got, const float *want, float tol, const char *fmt, ...) __attribute__((format(printf, 4, 5)));
static void expect4(const float *got, const float *want, float tol, const char *fmt, ...)
{
    va_list args;
    if (near4(got, want, tol) || bad++ >= 8)
        return;
    fprintf(stderr, "  mismatch: ");
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, ": got (%g %g %g %g), want (%g %g %g %g)\n", got[0], got[1], got[2], got[3], want[0], want[1], want[2],
            want[3]);
}
#define EXPECT4(got, want, tol, ...) expect4((got), (want), (tol), __VA_ARGS__)

/* ---- Reference sampling of RGBA32F 2D textures (clamp to edge) ---- */

struct ref_tex {
    int w, h, levels;
    const float *data[4]; /* level l: (w >> l) x (h >> l) texels of 4 floats */
};

static int ref_dim(int size, int level)
{
    return (size >> level) > 0 ? size >> level : 1;
}

static void ref_texel(const struct ref_tex *t, int l, int x, int y, float *out)
{
    int w = ref_dim(t->w, l), h = ref_dim(t->h, l);
    x = x < 0 ? 0 : x >= w ? w - 1 : x;
    y = y < 0 ? 0 : y >= h ? h - 1 : y;
    memcpy(out, t->data[l] + 4 * (y * w + x), 16);
}

/* One level, nearest or linear, with a texel offset. */
static void ref_level(const struct ref_tex *t, int l, float u, float v, bool linear, int ox, int oy, float *out)
{
    float w = (float)ref_dim(t->w, l), h = (float)ref_dim(t->h, l), uu, vv, a, b, t00[4], t10[4], t01[4], t11[4];
    int x0, y0, k;
    if (!linear) {
        ref_texel(t, l, (int)floorf(u * w) + ox, (int)floorf(v * h) + oy, out);
        return;
    }
    uu = u * w - 0.5f;
    vv = v * h - 0.5f;
    x0 = (int)floorf(uu) + ox;
    y0 = (int)floorf(vv) + oy;
    a = uu - floorf(uu);
    b = vv - floorf(vv);
    ref_texel(t, l, x0, y0, t00);
    ref_texel(t, l, x0 + 1, y0, t10);
    ref_texel(t, l, x0, y0 + 1, t01);
    ref_texel(t, l, x0 + 1, y0 + 1, t11);
    for (k = 0; k < 4; k++)
        out[k] = (1 - a) * (1 - b) * t00[k] + a * (1 - b) * t10[k] + (1 - a) * b * t01[k] + a * b * t11[k];
}

/* Explicit LOD: clamped to the levels; nearest mip d = ceil(lod + 0.5) - 1,
 * linear mip blends floor(lod) and the next level. The blend weight has
 * limited precision (Vulkan: mipmapPrecisionBits, 4 at least; Apple GPUs
 * about 5): ref_tolerance gives what that allows. */
static float ref_spread; /* largest difference between the two levels blended last */

static float ref_tolerance(void)
{
    return 0.02f + ref_spread / 16.0f;
}

static void ref_sample(const struct ref_tex *t, float u, float v, float lod, bool linear, int ox, int oy, float *out)
{
    float q = (float)(t->levels - 1), a[4], b[4], f;
    int d, k;
    lod = lod < 0 ? 0 : lod > q ? q : lod;
    if (!linear) {
        d = lod <= 0.5f ? 0 : (int)(ceilf(lod + 0.5f) - 1.0f);
        ref_level(t, d > t->levels - 1 ? t->levels - 1 : d, u, v, false, ox, oy, out);
        return;
    }
    d = (int)floorf(lod);
    f = lod - (float)d;
    ref_level(t, d, u, v, true, ox, oy, a);
    ref_level(t, d + 1 < t->levels ? d + 1 : d, u, v, true, ox, oy, b);
    ref_spread = 0;
    for (k = 0; k < 4; k++) {
        out[k] = a[k] + f * (b[k] - a[k]);
        if (f > 0 && fabsf(b[k] - a[k]) > ref_spread)
            ref_spread = fabsf(b[k] - a[k]);
    }
}

/* Gather footprint of level 0 with an offset: texels (i0,j1) (i1,j1) (i1,j0) (i0,j0). */
static void ref_gather(const struct ref_tex *t, float u, float v, int ox, int oy, int comp, float *out)
{
    float uu = u * (float)t->w - 0.5f, vv = v * (float)t->h - 0.5f, tx[4];
    int x0 = (int)floorf(uu) + ox, y0 = (int)floorf(vv) + oy, k;
    static const int dx[4] = { 0, 1, 1, 0 }, dy[4] = { 1, 1, 0, 0 };
    for (k = 0; k < 4; k++) {
        ref_texel(t, 0, x0 + dx[k], y0 + dy[k], tx);
        out[k] = tx[comp];
    }
}

/* Vulkan's cube face selection: face, then texel (size x size face). */
static void ref_cube(const float *d, int size, int *face, int *x, int *y, float *uo, float *vo)
{
    float ax = fabsf(d[0]), ay = fabsf(d[1]), az = fabsf(d[2]), sc, tc, ma, u, v;
    if (ax >= ay && ax >= az) {
        ma = ax;
        *face = d[0] >= 0 ? 0 : 1;
        sc = d[0] >= 0 ? -d[2] : d[2];
        tc = -d[1];
    } else if (ay >= az) {
        ma = ay;
        *face = d[1] >= 0 ? 2 : 3;
        sc = d[0];
        tc = d[1] >= 0 ? d[2] : -d[2];
    } else {
        ma = az;
        *face = d[2] >= 0 ? 4 : 5;
        sc = d[2] >= 0 ? d[0] : -d[0];
        tc = -d[1];
    }
    u = 0.5f * (sc / ma + 1.0f);
    v = 0.5f * (tc / ma + 1.0f);
    *x = (int)floorf(u * (float)size);
    *y = (int)floorf(v * (float)size);
    *x = *x < 0 ? 0 : *x >= size ? size - 1 : *x;
    *y = *y < 0 ? 0 : *y >= size ? size - 1 : *y;
    if (uo)
        *uo = u;
    if (vo)
        *vo = v;
}

static int ref_layer(float layer, int layers)
{
    float l = rintf(layer); /* round to nearest even */
    return l < 0 ? 0 : l > (float)(layers - 1) ? layers - 1 : (int)l;
}

/* ---- 2D sampling: LOD, gradients, offsets, fetch, projection, queries ---- */

static void run_image_sample(const uint32_t *words, size_t count)
{
    static const float cases[16][4] = {
        { 0.0625f, 0.0625f, 0.0f, 0.125f }, { 0.30f, 0.70f, 0.0f, 0.125f }, { 0.53f, 0.21f, 1.0f, 0.25f },
        { 0.80f, 0.45f, 2.0f, 0.5f },       { 0.15f, 0.90f, 0.25f, 0.125f }, { 0.66f, 0.33f, 1.25f, 0.25f },
        { 0.40f, 0.60f, 2.75f, 0.5f },      { 0.95f, 0.05f, 3.0f, 0.25f },   { 0.02f, 0.98f, 5.0f, 0.125f },
        { 0.55f, 0.45f, -1.0f, 0.125f },    { 0.27f, 0.43f, 0.6f, 0.25f },   { 0.71f, 0.88f, 1.6f, 0.5f },
        { 0.12f, 0.37f, 0.4f, 0.125f },     { 0.88f, 0.62f, 2.2f, 0.25f },   { 0.33f, 0.12f, 1.4f, 0.5f },
        { 0.58f, 0.77f, 0.0f, 0.25f },
    };
    static float levels[4][8 * 8 * 4];
    struct ref_tex rt;
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[5];
    id pso, tex, nearest, linear;
    int l, x, y, i;

    for (l = 0; l < 4; l++) {
        int w = 8 >> l;
        for (y = 0; y < w; y++)
            for (x = 0; x < w; x++) {
                float *t = &levels[l][4 * (y * w + x)];
                t[0] = l ? (float)(x + 10 * l) : (float)x;
                t[1] = l ? (float)(y + 10 * l) : (float)y;
                t[2] = l ? (float)l : (float)(x + 8 * y);
                t[3] = 1.0f;
            }
        rt.data[l] = levels[l];
    }
    rt.w = rt.h = 8;
    rt.levels = 4;

    REQUIRE(mt_translate(words, count, NULL, &res));
    CHECK(res.resource_count == 5 && res.resources[0].type == VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER &&
          res.resources[0].offset == 0 && res.resources[1].type == VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE &&
          res.resources[1].offset == 16 && res.resources[1].stride == 8 &&
          res.resources[2].type == VK_DESCRIPTOR_TYPE_SAMPLER && res.resources[2].offset == 32 &&
          res.resources[3].offset == 48 && res.resources[4].offset == 64);
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    tex = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 8, 8, 1, 1, 4, 1);
    for (l = 0; l < 4; l++)
        mt_upload(tex, (unsigned long)l, 0, (unsigned long)(8 >> l), (unsigned long)(8 >> l), 1, 16, levels[l]);
    nearest = mt_sampler(&smp_nearest);
    linear = mt_sampler(&smp_linear);
    in = mt_buffer(sizeof(cases), cases, sizeof(cases));
    out = mt_buffer(16 * 11 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, tex, nearest);
    b[1] = bind_tex(0, 1, 0, tex, NULL);
    b[2] = bind_tex(0, 2, 0, NULL, linear);
    b[3] = bind(0, 3, &in);
    b[4] = bind(0, 4, &out);
    CHECK(mt_dispatch(pso, &res, b, 5, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 16; i++) {
        const float *c = cases[i], *o = (const float *)out.data + 44 * i;
        float want[4], glod = log2f(c[3] * 8.0f);
        int lod = (int)c[2] < 0 ? 0 : (int)c[2] > 3 ? 3 : (int)c[2], fx, fy;
        ref_sample(&rt, c[0], c[1], c[2], false, 0, 0, want);
        EXPECT4(o + 0, want, 0.0f, "case %d textureLod nearest", i);
        ref_sample(&rt, c[0], c[1], c[2], true, 0, 0, want);
        EXPECT4(o + 4, want, ref_tolerance(), "case %d textureLod linear", i);
        ref_sample(&rt, c[0], c[1], 0.0f, false, 1, -1, want);
        EXPECT4(o + 8, want, 0.0f, "case %d textureLodOffset", i);
        ref_sample(&rt, c[0], c[1], glod, false, 0, 0, want);
        EXPECT4(o + 12, want, 0.0f, "case %d textureGrad", i);
        ref_sample(&rt, c[0], c[1], glod, true, -2, 1, want);
        EXPECT4(o + 16, want, ref_tolerance(), "case %d textureGradOffset linear", i);
        ref_texel(&rt, lod, (int)(c[0] * 8.0f) >> lod, (int)(c[1] * 8.0f) >> lod, want);
        EXPECT4(o + 20, want, 0.0f, "case %d texelFetch", i);
        fx = (int)(c[0] * 4.0f) & 2;
        fy = (int)(c[1] * 4.0f) & 2;
        ref_texel(&rt, 1, fx + 1, fy, want);
        EXPECT4(o + 24, want, 0.0f, "case %d texelFetchOffset", i);
        ref_sample(&rt, c[0], c[1], c[2], false, 0, 0, want);
        EXPECT4(o + 28, want, 0.0f, "case %d textureProjLod", i);
        want[0] = 8; want[1] = 8; want[2] = 2; want[3] = 2;
        EXPECT4(o + 32, want, 0.0f, "case %d textureSize", i);
        want[0] = 4; want[1] = 4; want[2] = 4; want[3] = 0;
        EXPECT4(o + 36, want, 0.0f, "case %d textureQueryLevels", i);
        ref_sample(&rt, c[0], c[1], glod > 2.0f ? glod : 2.0f, false, 0, 0, want); /* MinLod 2 */
        EXPECT4(o + 40, want, 0.0f, "case %d textureGradClampARB", i);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(tex);
    pvk_release(nearest);
    pvk_release(linear);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_image_sample(void)
{
    run_image_sample(spv_sample, PVK_ARRAY_SIZE(spv_sample));
}

static void test_image_sample_opt(void)
{
    run_image_sample(spv_sample_opt, PVK_ARRAY_SIZE(spv_sample_opt));
}

/* ---- Array layers and cube maps ---- */

static const float cube_dirs[16][4] = {
    { 1.0f, 0.3f, -0.6f, 0.0f },     { -1.0f, 0.2f, 0.7f, 1.0f },    { 0.4f, 1.0f, -0.3f, 0.6f },
    { 0.1f, -1.0f, 0.65f, 5.0f },    { -0.3f, 0.2f, 1.0f, -2.0f },   { 0.6f, -0.7f, -1.0f, 1.5f },
    { 0.9f, -0.15f, 0.35f, 0.4f },   { -0.8f, -0.6f, -0.1f, 1.0f },  { 0.15f, 0.85f, 0.6f, 0.0f },
    { -0.4f, -0.9f, -0.2f, 1.0f },   { 0.2f, -0.6f, 0.9f, 0.0f },    { -0.7f, 0.1f, -0.85f, 1.0f },
    { 2.0f, 0.55f, 1.1f, 0.0f },     { -0.1f, 3.0f, -1.3f, 1.0f },   { 0.45f, -0.35f, -0.9f, 0.5f },
    { -0.55f, 0.65f, 0.75f, 1.0f },
};

static void run_image_arrays(bool as_2d)
{
    static const float layers[16] = { 0.0f, 0.4f, 0.5f, 1.5f, 2.5f, 1.49f, -0.7f, 7.0f,
                                      2.51f, 1.0f, 0.6f, 1.2f, 2.0f, 0.51f, 3.5f, -0.5f };
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[7];
    float cases[32][4], data[16 * 4];
    int32_t idata[16 * 4];
    id pso, arr, cube, cubes, arr1d, itex, nearest;
    int i, l, x, y;

    for (i = 0; i < 16; i++) {
        cases[i][0] = 0.06f + 0.057f * (float)i;
        cases[i][1] = 0.93f - 0.053f * (float)i;
        cases[i][2] = layers[i];
        cases[i][3] = 0.0f;
        memcpy(cases[16 + i], cube_dirs[i], 16);
    }
    memset(&options, 0, sizeof(options));
    options.image_1d_as_2d = as_2d;
    MT_BUILD(spv_arrays, &options, res, pso);
    arr = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 3, 1, 1);
    cube = mt_texture(PVK_MTLTextureTypeCube, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    cubes = mt_texture(PVK_MTLTextureTypeCubeArray, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 2, 1, 1);
    arr1d = as_2d ? mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 8, 1, 1, 2, 1, 1)
                  : mt_texture(PVK_MTLTextureType1DArray, PVK_MTLPixelFormatRGBA32Float, 8, 1, 1, 2, 1, 1);
    for (l = 0; l < 12; l++) { /* 2D array layers, cube faces, cube array slices (cube * 6 + face) */
        for (y = 0; y < 4; y++)
            for (x = 0; x < 4; x++) {
                float *t = &data[4 * (y * 4 + x)];
                t[0] = (float)(l < 6 ? l : 10 + l - 6);
                t[1] = (float)x;
                t[2] = (float)y;
                t[3] = 1.0f;
            }
        if (l < 3)
            mt_upload(arr, 0, (unsigned long)l, 4, 4, 1, 16, data);
        if (l < 6)
            mt_upload(cube, 0, (unsigned long)l, 4, 4, 1, 16, data);
        mt_upload(cubes, 0, (unsigned long)l, 4, 4, 1, 16, data);
    }
    for (l = 0; l < 2; l++) {
        for (x = 0; x < 8; x++) {
            data[4 * x + 0] = (float)x;
            data[4 * x + 1] = (float)(10 * l);
            data[4 * x + 2] = 0.0f;
            data[4 * x + 3] = 1.0f;
        }
        mt_upload(arr1d, 0, (unsigned long)l, 8, 1, 1, 16, data);
    }
    for (y = 0; y < 4; y++)
        for (x = 0; x < 4; x++) {
            idata[4 * (y * 4 + x) + 0] = 10 * x - 5;
            idata[4 * (y * 4 + x) + 1] = 100 * y;
            idata[4 * (y * 4 + x) + 2] = -x;
            idata[4 * (y * 4 + x) + 3] = 7;
        }
    itex = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Sint, 4, 4, 1, 1, 1, 1);
    mt_upload(itex, 0, 0, 4, 4, 1, 16, idata);
    nearest = mt_sampler(&smp_nearest);
    in = mt_buffer(sizeof(cases), cases, sizeof(cases));
    out = mt_buffer(16 * 7 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, arr, nearest);
    b[1] = bind_tex(0, 1, 0, cube, nearest);
    b[2] = bind_tex(0, 2, 0, cubes, nearest);
    b[3] = bind_tex(0, 3, 0, arr1d, nearest);
    b[4] = bind(0, 4, &in);
    b[5] = bind(0, 5, &out);
    b[6] = bind_tex(0, 6, 0, itex, nearest);
    CHECK(mt_dispatch(pso, &res, b, 7, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 16; i++) {
        const float *c = cases[i], *d = cube_dirs[i], *o = (const float *)out.data + 28 * i;
        float want[4];
        int f, fx, fy, L = ref_layer(c[2], 3);
        want[0] = (float)L;
        want[1] = floorf(c[0] * 4.0f);
        want[2] = floorf(c[1] * 4.0f);
        want[3] = 1.0f;
        EXPECT4(o + 0, want, 0.0f, "case %d 2D array layer %g", i, c[2]);
        ref_cube(d, 4, &f, &fx, &fy, NULL, NULL);
        want[0] = (float)f;
        want[1] = (float)fx;
        want[2] = (float)fy;
        EXPECT4(o + 4, want, 0.0f, "case %d cube (%g %g %g)", i, d[0], d[1], d[2]);
        want[0] = (float)(10 * ref_layer(d[3], 2) + f);
        EXPECT4(o + 8, want, 0.0f, "case %d cube array layer %g", i, d[3]);
        want[0] = (float)(i % 3);
        want[1] = floorf(c[0] * 4.0f);
        want[2] = floorf(c[1] * 4.0f);
        EXPECT4(o + 12, want, 0.0f, "case %d texelFetch 2D array", i);
        want[0] = floorf(c[0] * 8.0f);
        want[1] = (float)(10 * ref_layer(c[2], 2));
        want[2] = 0.0f;
        EXPECT4(o + 16, want, 0.0f, "case %d 1D array (%s)", i, as_2d ? "as 2D" : "1D");
        want[0] = 4;
        want[1] = 4;
        want[2] = 3;
        want[3] = 2;
        EXPECT4(o + 20, want, 0.0f, "case %d sizes", i);
        x = (int)floorf(c[0] * 4.0f);
        y = (int)floorf(c[1] * 4.0f);
        want[0] = (float)(10 * x - 5);
        want[1] = (float)(100 * y);
        want[2] = (float)-x;
        want[3] = 7.0f;
        EXPECT4(o + 24, want, 0.0f, "case %d integer textureLod", i);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(arr);
    pvk_release(cube);
    pvk_release(cubes);
    pvk_release(arr1d);
    pvk_release(itex);
    pvk_release(nearest);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_image_arrays(void)
{
    run_image_arrays(false);
    run_image_arrays(true);
}

/* ---- Depth comparison ---- */

static void test_image_depth(void)
{
    static const float cases[16][4] = { /* u, v, reference, lod */
        { 0.1f, 0.1f, 0.02f, 0.0f },  { 0.1f, 0.1f, 0.04f, 0.0f },  { 0.6f, 0.3f, 0.3f, 0.0f },
        { 0.6f, 0.3f, 0.4f, 1.0f },   { 0.9f, 0.9f, 0.9f, 0.0f },   { 0.9f, 0.9f, 0.99f, 0.0f },
        { 0.35f, 0.65f, 0.5f, 1.0f }, { 0.35f, 0.65f, 0.6f, 0.0f }, { 0.15f, 0.85f, 0.75f, 1.0f },
        { 0.85f, 0.15f, 0.2f, 0.0f }, { 0.4f, 0.4f, 0.33f, 1.0f },  { 0.55f, 0.8f, 0.8f, 0.0f },
        { 0.7f, 0.6f, 0.6f, 1.0f },   { 0.2f, 0.45f, 0.55f, 0.0f }, { 0.5f, 0.5f, 0.0f, 0.0f },
        { 0.5f, 0.5f, 1.0f, 1.0f },
    };
    static const struct mt_sampler_desc less = { PVK_MTLSamplerMinMagFilterNearest, 1, PVK_MTLSamplerAddressModeClampToEdge,
                                                 false, PVK_MTLCompareFunctionLess };
    static const struct mt_sampler_desc less_linear = { PVK_MTLSamplerMinMagFilterLinear, 1,
                                                        PVK_MTLSamplerAddressModeClampToEdge, false,
                                                        PVK_MTLCompareFunctionLess };
    static const struct mt_sampler_desc greater = { PVK_MTLSamplerMinMagFilterNearest, 1,
                                                    PVK_MTLSamplerAddressModeClampToEdge, false,
                                                    PVK_MTLCompareFunctionGreater };
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[7];
    float d0[16], d1[4], darr[2][16], dcube[6][4], all[32][4];
    id pso, depth, arr, cube, s_less, s_linear, s_greater;
    int i, x, y, l, k;

    for (i = 0; i < 16; i++) {
        d0[i] = ((float)i + 0.5f) / 16.0f;      /* texel (x, y) = x + 4y */
        darr[0][i] = d0[i];
        darr[1][i] = 1.0f - d0[i];
    }
    for (i = 0; i < 4; i++)
        d1[i] = 0.1f + 0.25f * (float)i;
    for (l = 0; l < 6; l++)
        for (i = 0; i < 4; i++)
            dcube[l][i] = ((float)l + 0.5f) / 6.0f;
    memcpy(all, cases, sizeof(cases));
    memcpy(all[16], cube_dirs, sizeof(cube_dirs));

    MT_BUILD(spv_depth, NULL, res, pso);
    depth = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatDepth32Float, 4, 4, 1, 1, 2, 1);
    arr = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatDepth32Float, 4, 4, 1, 2, 1, 1);
    cube = mt_texture(PVK_MTLTextureTypeCube, PVK_MTLPixelFormatDepth32Float, 2, 2, 1, 1, 1, 1);
    mt_upload(depth, 0, 0, 4, 4, 1, 4, d0);
    mt_upload(depth, 1, 0, 2, 2, 1, 4, d1);
    for (l = 0; l < 2; l++)
        mt_upload(arr, 0, (unsigned long)l, 4, 4, 1, 4, darr[l]);
    for (l = 0; l < 6; l++)
        mt_upload(cube, 0, (unsigned long)l, 2, 2, 1, 4, dcube[l]);
    s_less = mt_sampler(&less);
    s_linear = mt_sampler(&less_linear);
    s_greater = mt_sampler(&greater);
    in = mt_buffer(sizeof(all), all, sizeof(all));
    out = mt_buffer(16 * 4 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, depth, s_less);
    b[1] = bind_tex(0, 1, 0, arr, s_linear);
    b[2] = bind_tex(0, 2, 0, cube, s_less);
    b[3] = bind_tex(0, 3, 0, depth, NULL);
    b[4] = bind_tex(0, 4, 0, NULL, s_greater);
    b[5] = bind(0, 5, &in);
    b[6] = bind(0, 6, &out);
    CHECK(mt_dispatch(pso, &res, b, 7, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 16; i++) {
        const float *c = cases[i], *o = (const float *)out.data + 16 * i;
        float want[4], ref = c[2], uu, vv, a, bb, pcf = 0;
        int x0, y0, f, fx, fy;
        x = (int)floorf(c[0] * 4.0f);
        y = (int)floorf(c[1] * 4.0f);
        /* textureLod (level c.w), offset (1, 0), projective, gradient (level 1) */
        want[0] = c[3] > 0.5f ? (ref < d1[(int)floorf(c[1] * 2.0f) * 2 + (int)floorf(c[0] * 2.0f)] ? 1.0f : 0.0f)
                              : (ref < d0[y * 4 + x] ? 1.0f : 0.0f);
        want[1] = ref < d0[y * 4 + (x + 1 > 3 ? 3 : x + 1)] ? 1.0f : 0.0f;
        want[2] = ref < d0[y * 4 + x] ? 1.0f : 0.0f;
        want[3] = ref < d1[(int)floorf(c[1] * 2.0f) * 2 + (int)floorf(c[0] * 2.0f)] ? 1.0f : 0.0f;
        EXPECT4(o + 0, want, 0.0f, "case %d compare (lod, offset, proj, grad)", i);
        uu = c[0] * 4.0f - 0.5f;
        vv = c[1] * 4.0f - 0.5f;
        x0 = (int)floorf(uu);
        y0 = (int)floorf(vv);
        for (k = 0; k < 4; k++) { /* gather: (i0,j1) (i1,j1) (i1,j0) (i0,j0) */
            int gx = x0 + (k == 1 || k == 2), gy = y0 + (k < 2);
            gx = gx < 0 ? 0 : gx > 3 ? 3 : gx;
            gy = gy < 0 ? 0 : gy > 3 ? 3 : gy;
            want[k] = ref < d0[gy * 4 + gx] ? 1.0f : 0.0f;
        }
        EXPECT4(o + 4, want, 0.0f, "case %d textureGather compare", i);
        a = uu - floorf(uu);
        bb = vv - floorf(vv);
        for (k = 0; k < 4; k++) { /* linear filter of the comparisons (layer i % 2) */
            int gx = x0 + (k & 1), gy = y0 + (k >> 1);
            float w = ((k & 1) ? a : 1 - a) * ((k >> 1) ? bb : 1 - bb);
            gx = gx < 0 ? 0 : gx > 3 ? 3 : gx;
            gy = gy < 0 ? 0 : gy > 3 ? 3 : gy;
            pcf += w * (ref < darr[i % 2][gy * 4 + gx] ? 1.0f : 0.0f);
        }
        ref_cube(cube_dirs[i], 2, &f, &fx, &fy, NULL, NULL);
        want[0] = pcf;
        want[1] = ref < dcube[f][0] ? 1.0f : 0.0f;
        want[2] = ref > d0[y * 4 + x] ? 1.0f : 0.0f; /* the separate GREATER sampler */
        want[3] = d0[y * 4 + x];
        EXPECT4(o + 8, want, 1.0f / 16.0f, "case %d (array PCF, cube, separate sampler, fetch)", i);
        EXPECT(fabsf(o[12] - d0[y * 4 + x]) == 0.0f, "case %d depth fetch as color: %g %g %g %g", i, o[12], o[13], o[14],
               o[15]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(depth);
    pvk_release(arr);
    pvk_release(cube);
    pvk_release(s_less);
    pvk_release(s_linear);
    pvk_release(s_greater);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Gather ---- */

static void run_image_gather(const uint32_t *words, size_t count)
{
    static const float gdirs[16][4] = { /* cube directions whose footprint stays inside a face */
        { 1.0f, 0.1f, -0.2f, 0 },  { -1.0f, -0.15f, 0.1f, 0 }, { 0.2f, 1.0f, -0.1f, 0 },  { -0.1f, -1.0f, 0.2f, 0 },
        { 0.15f, -0.2f, 1.0f, 0 }, { -0.2f, 0.1f, -1.0f, 0 },  { 1.0f, -0.3f, 0.35f, 0 }, { -1.0f, 0.3f, -0.35f, 0 },
        { 0.3f, 1.0f, 0.35f, 0 },  { -0.3f, -1.0f, -0.4f, 0 }, { 0.4f, 0.3f, 1.0f, 0 },   { 0.3f, -0.4f, -1.0f, 0 },
        { 1.0f, 0.4f, 0.4f, 0 },   { 0.05f, 1.0f, 0.05f, 0 },  { -0.4f, 0.4f, 1.0f, 0 },  { 0.0f, 0.0f, -1.0f, 0 },
    };
    struct {
        float cases[16][4];
        float dirs[16][4];
        int32_t offs[16][2];
    } input;
    static float tdata[16 * 4], cdata[6][16 * 4], adata[2][16 * 4];
    int32_t idata[16 * 4];
    struct ref_tex rt, rl, rc;
    struct pvk_msl_result res;
    struct mt_buffer in, out;
    struct mt_binding b[6];
    id pso, tex, itex, arr, cube, linear;
    int i, x, y, l, k;

    for (y = 0; y < 4; y++)
        for (x = 0; x < 4; x++) {
            int t = y * 4 + x;
            tdata[4 * t + 0] = (float)x;
            tdata[4 * t + 1] = (float)y;
            tdata[4 * t + 2] = (float)(x + 4 * y);
            tdata[4 * t + 3] = (float)(100 + x + 4 * y);
            idata[4 * t + 0] = x - 2;
            idata[4 * t + 1] = 3 * y;
            idata[4 * t + 2] = -x - 4 * y;
            idata[4 * t + 3] = 7;
            for (l = 0; l < 2; l++) {
                adata[l][4 * t + 0] = (float)(x + 10 * l);
                adata[l][4 * t + 1] = (float)(y + 10 * l);
                adata[l][4 * t + 2] = (float)(x + 4 * y + 10 * l);
                adata[l][4 * t + 3] = (float)l;
            }
            for (l = 0; l < 6; l++) {
                cdata[l][4 * t + 0] = (float)(16 * l + t);
                cdata[l][4 * t + 1] = 0.0f;
                cdata[l][4 * t + 2] = 0.0f;
                cdata[l][4 * t + 3] = 0.0f;
            }
        }
    for (i = 0; i < 16; i++) {
        input.cases[i][0] = 0.08f + 0.055f * (float)i;
        input.cases[i][1] = 0.87f - 0.051f * (float)i;
        input.cases[i][2] = input.cases[i][3] = 0.0f;
        memcpy(input.dirs[i], gdirs[i], 16);
        input.offs[i][0] = i % 3 - 1;
        input.offs[i][1] = 1 - i % 2 * 3;
    }
    rt.w = rt.h = rl.w = rl.h = rc.w = rc.h = 4;
    rt.levels = rl.levels = rc.levels = 1;
    rt.data[0] = tdata;
    rl.data[0] = adata[1];

    REQUIRE(mt_translate(words, count, NULL, &res));
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    tex = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    itex = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Sint, 4, 4, 1, 1, 1, 1);
    arr = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 2, 1, 1);
    cube = mt_texture(PVK_MTLTextureTypeCube, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    mt_upload(tex, 0, 0, 4, 4, 1, 16, tdata);
    mt_upload(itex, 0, 0, 4, 4, 1, 16, idata);
    for (l = 0; l < 2; l++)
        mt_upload(arr, 0, (unsigned long)l, 4, 4, 1, 16, adata[l]);
    for (l = 0; l < 6; l++)
        mt_upload(cube, 0, (unsigned long)l, 4, 4, 1, 16, cdata[l]);
    linear = mt_sampler(&smp_linear);
    in = mt_buffer(sizeof(input), &input, sizeof(input));
    out = mt_buffer(16 * 8 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, tex, linear);
    b[1] = bind_tex(0, 1, 0, itex, linear);
    b[2] = bind_tex(0, 2, 0, arr, linear);
    b[3] = bind_tex(0, 3, 0, cube, linear);
    b[4] = bind(0, 4, &in);
    b[5] = bind(0, 5, &out);
    CHECK(mt_dispatch(pso, &res, b, 6, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 16; i++) {
        const float *o = (const float *)out.data + 32 * i;
        float u = input.cases[i][0], v = input.cases[i][1], want[4], cu, cv;
        static const int offs4[4][2] = { { 0, 0 }, { 1, 0 }, { 0, 1 }, { -1, -1 } };
        int f, fx, fy;
        ref_gather(&rt, u, v, 0, 0, 0, want);
        EXPECT4(o + 0, want, 0.0f, "case %d gather x", i);
        ref_gather(&rt, u, v, 0, 0, 3, want);
        EXPECT4(o + 4, want, 0.0f, "case %d gather w", i);
        ref_gather(&rt, u, v, 1, -1, 2, want);
        EXPECT4(o + 8, want, 0.0f, "case %d gather offset (1, -1)", i);
        ref_gather(&rt, u, v, input.offs[i][0], input.offs[i][1], 1, want);
        EXPECT4(o + 12, want, 0.0f, "case %d gather dynamic offset (%d, %d)", i, input.offs[i][0], input.offs[i][1]);
        for (k = 0; k < 4; k++) {
            float g[4];
            ref_gather(&rt, u, v, offs4[k][0], offs4[k][1], 0, g);
            want[k] = g[3];
        }
        EXPECT4(o + 16, want, 0.0f, "case %d gather offsets", i);
        {
            float uu = u * 4.0f - 0.5f, vv = v * 4.0f - 0.5f;
            int x0 = (int)floorf(uu), y0 = (int)floorf(vv);
            for (k = 0; k < 4; k++) {
                int gx = x0 + (k == 1 || k == 2), gy = y0 + (k < 2);
                gx = gx < 0 ? 0 : gx > 3 ? 3 : gx;
                gy = gy < 0 ? 0 : gy > 3 ? 3 : gy;
                want[k] = (float)idata[4 * (gy * 4 + gx) + 1];
            }
        }
        EXPECT4(o + 20, want, 0.0f, "case %d integer gather", i);
        ref_gather(&rl, u, v, 0, 0, 2, want);
        EXPECT4(o + 24, want, 0.0f, "case %d gather array layer 1", i);
        ref_cube(gdirs[i], 4, &f, &fx, &fy, &cu, &cv);
        rc.data[0] = cdata[f];
        ref_gather(&rc, cu, cv, 0, 0, 0, want);
        EXPECT4(o + 28, want, 0.0f, "case %d gather cube face %d", i, f);
    }
    CHECK(bad == 0);
    mt_buffer_free(&in);
    mt_buffer_free(&out);
    pvk_release(tex);
    pvk_release(itex);
    pvk_release(arr);
    pvk_release(cube);
    pvk_release(linear);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_image_gather(void)
{
    run_image_gather(spv_gather, PVK_ARRAY_SIZE(spv_gather));
}

static void test_image_gather_opt(void)
{
    run_image_gather(spv_gather_opt, PVK_ARRAY_SIZE(spv_gather_opt));
}

/* ---- Storage images ---- */

static float half_to_float(uint16_t h)
{
    return pvk_spv_half_to_float(h);
}

static uint16_t float_to_half(float f) /* exact for the small integers and halves used here */
{
    uint32_t bits, sign, exp, mant;
    memcpy(&bits, &f, 4);
    sign = (bits >> 16) & 0x8000u;
    exp = (bits >> 23) & 0xffu;
    mant = bits & 0x7fffffu;
    if (exp == 0)
        return (uint16_t)sign;
    return (uint16_t)(sign | ((exp - 112u) << 10) | (mant >> 13));
}

static void run_image_storage(const uint32_t *words, size_t count, bool as_2d)
{
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b[9];
    static float src[16 * 4], noformat[16 * 4], got[16 * 4];
    static uint32_t vol[64];
    static uint16_t layers[3][16 * 4];
    id pso, t_src, t_dst, t_vol, t_layers, t_cube, t_line, t_noformat, t_cubes;
    int i, k, l, f;

    for (i = 0; i < 16; i++) {
        for (k = 0; k < 4; k++) {
            src[4 * i + k] = (float)(i * 4 + k) * 0.25f;
            noformat[4 * i + k] = (float)(10 * i + k);
        }
        for (l = 0; l < 3; l++) {
            layers[l][4 * i + 0] = float_to_half((float)(i % 4));
            layers[l][4 * i + 1] = float_to_half((float)(i / 4));
            layers[l][4 * i + 2] = float_to_half((float)l);
            layers[l][4 * i + 3] = float_to_half(0.5f);
        }
    }
    for (i = 0; i < 64; i++)
        vol[i] = (uint32_t)i;
    memset(&options, 0, sizeof(options));
    options.image_1d_as_2d = as_2d;
    REQUIRE(mt_translate(words, count, &options, &res));
    CHECK(res.resource_count == 9 && res.resources[0].type == VK_DESCRIPTOR_TYPE_STORAGE_IMAGE &&
          !res.resources[0].writable && res.resources[1].writable && res.resources[2].writable);
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    t_src = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    t_dst = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    t_vol = mt_texture(PVK_MTLTextureType3D, PVK_MTLPixelFormatR32Uint, 4, 4, 4, 1, 1, 1);
    t_layers = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA16Float, 4, 4, 1, 3, 1, 1);
    t_cube = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA8Unorm, 4, 4, 1, 6, 1, 1); /* cubes: 2D arrays */
    t_line = as_2d ? mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Sint, 16, 1, 1, 1, 1, 1)
                   : mt_texture(PVK_MTLTextureType1D, PVK_MTLPixelFormatR32Sint, 16, 1, 1, 1, 1, 1);
    t_noformat = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    t_cubes = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 2, 2, 1, 12, 1, 1);
    mt_upload(t_src, 0, 0, 4, 4, 1, 16, src);
    mt_upload(t_vol, 0, 0, 4, 4, 4, 4, vol);
    for (l = 0; l < 3; l++)
        mt_upload(t_layers, 0, (unsigned long)l, 4, 4, 1, 8, layers[l]);
    mt_upload(t_noformat, 0, 0, 4, 4, 1, 16, noformat);
    out = mt_buffer(96 * 16 + 3 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, t_src, NULL);
    b[1] = bind_tex(0, 1, 0, t_dst, NULL);
    b[2] = bind_tex(0, 2, 0, t_vol, NULL);
    b[3] = bind_tex(0, 3, 0, t_layers, NULL);
    b[4] = bind_tex(0, 4, 0, t_cube, NULL);
    b[5] = bind_tex(0, 5, 0, t_line, NULL);
    b[6] = bind_tex(0, 6, 0, t_noformat, NULL);
    b[7] = bind_tex(0, 7, 0, t_cubes, NULL);
    b[8] = bind(0, 8, &out);
    CHECK(mt_dispatch(pso, &res, b, 9, NULL, 0, 1, 1, 1));

    bad = 0;
    mt_download(t_dst, 0, 0, 4, 4, 1, 16, got);
    for (i = 0; i < 16; i++)
        for (k = 0; k < 4; k++) {
            float want = src[4 * i + k] * 2.0f + (k == 0 ? (float)(i % 4) : k == 1 ? (float)(i / 4) : 0.0f);
            EXPECT(got[4 * i + k] == want, "dst[%d].%d = %g, want %g", i, k, got[4 * i + k], want);
        }
    mt_download(t_vol, 0, 0, 4, 4, 4, 4, vol);
    for (i = 0; i < 64; i++)
        EXPECT(vol[i] == (uint32_t)i * 3u + (uint32_t)(i / 16), "vol[%d] = %u", i, vol[i]);
    for (l = 0; l < 3; l++) {
        uint16_t h[16 * 4];
        mt_download(t_layers, 0, (unsigned long)l, 4, 4, 1, 8, h);
        for (i = 0; i < 16; i++) {
            float want[4], g[4];
            want[0] = (float)(i % 4 + l);
            want[1] = (float)(i / 4 + l);
            want[2] = (float)(2 * l);
            want[3] = 0.5f + (float)l;
            for (k = 0; k < 4; k++)
                g[k] = half_to_float(h[4 * i + k]);
            EXPECT4(g, want, 0.0f, "layers[%d][%d]", l, i);
        }
    }
    for (f = 0; f < 6; f++) {
        uint8_t px[16 * 4];
        mt_download(t_cube, 0, (unsigned long)f, 4, 4, 1, 4, px);
        for (i = 0; i < 16; i++) {
            const float *back = (const float *)out.data + 4 * (f * 16 + i);
            float want[4];
            want[0] = roundf((float)f / 8.0f * 255.0f) / 255.0f;
            want[1] = roundf((float)(i % 4) / 4.0f * 255.0f) / 255.0f;
            want[2] = roundf((float)(i / 4) / 4.0f * 255.0f) / 255.0f;
            want[3] = 1.0f;
            EXPECT4(back, want, 1e-6f, "cube face %d texel %d read back after the write", f, i);
            EXPECT(px[4 * i + 0] == (uint8_t)roundf((float)f / 8.0f * 255.0f) &&
                       px[4 * i + 1] == (uint8_t)roundf((float)(i % 4) / 4.0f * 255.0f) && px[4 * i + 3] == 255,
                   "cube face %d texel %d = %u %u %u %u", f, i, px[4 * i], px[4 * i + 1], px[4 * i + 2], px[4 * i + 3]);
        }
    }
    {
        int32_t line[16];
        mt_download(t_line, 0, 0, 16, 1, 1, 4, line);
        for (i = 0; i < 16; i++)
            EXPECT(line[i] == -i, "line[%d] = %d", i, line[i]);
    }
    mt_download(t_noformat, 0, 0, 4, 4, 1, 16, got);
    for (i = 0; i < 16; i++)
        for (k = 0; k < 4; k++)
            EXPECT(got[4 * i + k] == noformat[4 * i + 3 - k], "noformat[%d].%d = %g", i, k, got[4 * i + k]);
    for (l = 0; l < 12; l++) {
        float c[4 * 4];
        mt_download(t_cubes, 0, (unsigned long)l, 2, 2, 1, 16, c);
        for (i = 0; i < 4; i++) {
            float want[4];
            want[0] = (float)l;
            want[1] = (float)(i % 2);
            want[2] = (float)(i / 2);
            want[3] = 0.5f;
            EXPECT4(c + 4 * i, want, 0.0f, "cube array slice %d texel %d", l, i);
        }
    }
    {
        const int32_t *s = (const int32_t *)((const float *)out.data + 96 * 4);
        static const int32_t want[12] = { 4, 4, 4, 3, 4, 4, 16, 2, 4, 4, 2, 2 };
        for (k = 0; k < 12; k++)
            EXPECT(s[k] == want[k], "imageSize %d = %d, want %d", k, s[k], want[k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(t_src);
    pvk_release(t_dst);
    pvk_release(t_vol);
    pvk_release(t_layers);
    pvk_release(t_cube);
    pvk_release(t_line);
    pvk_release(t_noformat);
    pvk_release(t_cubes);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

