/* Storage images of one undecorated type get the access their use asks for
 * (pvk_spv_image_access): src read only, dst written only, acc both, and
 * only acc's writes fence (its reads after them see them). */
static void test_image_access_from_use(void)
{
    struct pvk_msl_result res;
    struct mt_binding b[3];
    float src[16 * 4], acc[32 * 4], got[16 * 4];
    id pso, t_src, t_dst, t_acc;
    int i;

    REQUIRE(mt_translate(spv_image_access, PVK_ARRAY_SIZE(spv_image_access), NULL, &res));
    CHECK(strstr(res.msl, "texture2d<float, access::read>, ") != NULL);  /* src */
    CHECK(strstr(res.msl, "texture2d<float, access::write>, ") != NULL); /* dst */
    CHECK(strstr(res.msl, "texture2d<float, access::read_write>, ") != NULL); /* acc */
    CHECK(strstr(res.msl, ".fence();") != NULL && strstr(strstr(res.msl, ".fence();") + 1, ".fence();") != NULL);
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    for (i = 0; i < 64; i++)
        src[i] = (float)i;
    for (i = 0; i < 128; i++)
        acc[i] = 100.0f;
    t_src = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    t_dst = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    t_acc = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 8, 1, 1, 1, 1);
    mt_upload(t_src, 0, 0, 4, 4, 1, 16, src);
    mt_upload(t_acc, 0, 0, 4, 8, 1, 16, acc);
    b[0] = bind_tex(0, 0, 0, t_src, NULL);
    b[1] = bind_tex(0, 1, 0, t_dst, NULL);
    b[2] = bind_tex(0, 2, 0, t_acc, NULL);
    CHECK(mt_dispatch(pso, &res, b, 3, NULL, 0, 1, 1, 1));
    mt_download(t_dst, 0, 0, 4, 4, 1, 16, got);
    mt_download(t_acc, 0, 0, 4, 8, 1, 16, acc);
    bad = 0;
    for (i = 0; i < 64; i++) {
        EXPECT(got[i] == src[i] * 2.0f, "dst %d = %g, want %g", i, got[i], src[i] * 2.0f);
        EXPECT(acc[i] == 100.0f + src[i], "acc %d = %g, want %g", i, acc[i], 100.0f + src[i]);
        EXPECT(acc[64 + i] == 100.0f + src[i], "acc %d = %g, want %g", 64 + i, acc[64 + i], 100.0f + src[i]);
    }
    CHECK(bad == 0);
    pvk_release(t_src);
    pvk_release(t_dst);
    pvk_release(t_acc);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Image atomics ---- */

static void test_image_atomics(void)
{
    struct pvk_msl_result res;
    struct mt_buffer out, bits;
    struct mt_binding b[7];
    uint32_t zero[64], v[64], *o, seen[16], layer_counts[2][6];
    int32_t mm[2][4], misc[4];
    id pso, t_counters, t_minmax, t_bits, t_vol, t_layers, t_misc;
    int i, k, f;

    memset(zero, 0, sizeof(zero));
    MT_BUILD(spv_atomics_img, NULL, res, pso);
    t_counters = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 4, 4, 1, 1, 1, 1);
    t_minmax = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatR32Sint, 2, 2, 1, 2, 1, 1);
    bits = mt_buffer(64, NULL, 0);
    t_bits = mt_texture_buffer(&bits, PVK_MTLPixelFormatR32Uint, 8, 4);
    t_vol = mt_texture(PVK_MTLTextureType3D, PVK_MTLPixelFormatR32Uint, 2, 2, 2, 1, 1, 1);
    t_layers = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatR32Uint, 2, 2, 1, 6, 1, 1);
    t_misc = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Sint, 2, 2, 1, 1, 1, 1);
    mt_upload(t_counters, 0, 0, 4, 4, 1, 4, zero);
    for (i = 0; i < 4; i++) {
        mm[0][i] = -100;
        mm[1][i] = 100;
    }
    mt_upload(t_minmax, 0, 0, 2, 2, 1, 4, mm[0]);
    mt_upload(t_minmax, 0, 1, 2, 2, 1, 4, mm[1]);
    mt_upload(t_vol, 0, 0, 2, 2, 2, 4, zero);
    for (f = 0; f < 6; f++)
        mt_upload(t_layers, 0, (unsigned long)f, 2, 2, 1, 4, zero);
    misc[0] = 1000;
    misc[1] = 500;
    misc[2] = 0;
    misc[3] = -1;
    mt_upload(t_misc, 0, 0, 2, 2, 1, 4, misc);
    out = mt_buffer(64 * 4 * 4, NULL, 0);
    b[0] = bind_tex(0, 0, 0, t_counters, NULL);
    b[1] = bind_tex(0, 1, 0, t_minmax, NULL);
    b[2] = bind_tex(0, 2, 0, t_bits, NULL);
    b[2].buf = &bits;
    b[3] = bind_tex(0, 3, 0, t_vol, NULL);
    b[4] = bind_tex(0, 4, 0, t_layers, NULL);
    b[5] = bind_tex(0, 5, 0, t_misc, NULL);
    b[6] = bind(0, 6, &out);
    CHECK(mt_dispatch(pso, &res, b, 7, NULL, 0, 1, 1, 1));

    bad = 0;
    o = out.data;
    mt_download(t_counters, 0, 0, 4, 4, 1, 4, v);
    memset(seen, 0, sizeof(seen));
    for (i = 0; i < 16; i++)
        EXPECT(v[i] == 4, "counter %d = %u", i, v[i]);
    for (i = 0; i < 64; i++) { /* each texel's four adds returned 0, 1, 2, 3 */
        EXPECT(o[4 * i] < 4, "add %d returned %u", i, o[4 * i]);
        if (o[4 * i] < 4)
            seen[i % 16] |= 1u << o[4 * i];
    }
    for (i = 0; i < 16; i++)
        EXPECT(seen[i] == 15, "texel %d: adds returned mask %x", i, seen[i]);
    mt_download(t_minmax, 0, 0, 2, 2, 1, 4, mm[0]);
    mt_download(t_minmax, 0, 1, 2, 2, 1, 4, mm[1]);
    for (i = 0; i < 4; i++) {
        EXPECT(mm[0][i] == 30 + i, "max[%d] = %d", i, mm[0][i]);
        EXPECT(mm[1][i] == i - 30, "min[%d] = %d", i, mm[1][i]);
    }
    for (i = 0; i < 8; i++)
        EXPECT(((uint32_t *)bits.data)[i] == 0xffu, "bits[%d] = %x", i, ((uint32_t *)bits.data)[i]);
    mt_download(t_vol, 0, 0, 2, 2, 2, 4, v);
    for (k = 0; k < 8; k++) {
        uint32_t want = 0;
        for (i = k; i < 64; i += 8)
            want ^= (uint32_t)i * 0x01010101u;
        EXPECT(v[k] == want, "xor[%d] = %x, want %x", k, v[k], want);
    }
    memset(layer_counts, 0, sizeof(layer_counts));
    for (i = 0; i < 64; i++)
        layer_counts[i % 2][(i / 2) % 6]++;
    for (f = 0; f < 6; f++) {
        mt_download(t_layers, 0, (unsigned long)f, 2, 2, 1, 4, v);
        EXPECT(v[0] == layer_counts[0][f] && v[1] == layer_counts[1][f] && v[2] == 0 && v[3] == 0,
               "layer %d = %u %u %u %u", f, v[0], v[1], v[2], v[3]);
    }
    for (i = 0; i < 64; i++)
        EXPECT(o[4 * i + 1] < layer_counts[i % 2][(i / 2) % 6], "array add %d returned %u", i, o[4 * i + 1]);
    mt_download(t_misc, 0, 0, 2, 2, 1, 4, misc);
    {
        /* exchanges: the 64 old values and the final one are 1000 and 0..63, once each */
        uint64_t have = 0;
        int inits = 0;
        for (i = 0; i <= 64; i++) {
            int32_t x = i < 64 ? (int32_t)o[4 * i + 2] : misc[0];
            if (x == 1000)
                inits++;
            else if (x >= 0 && x < 64)
                have |= 1ull << x;
        }
        EXPECT(inits == 1 && have == ~0ull, "exchange values (final %d, %d initial values)", misc[0], inits);
    }
    EXPECT(misc[1] == 500 - 64, "compare-exchange counter = %d", misc[1]);
    EXPECT(misc[2] == -63, "min = %d", misc[2]);
    EXPECT(misc[3] == (int32_t)0x80000000u, "and = %x", (uint32_t)misc[3]);
    for (i = 0; i < 64; i++)
        EXPECT(o[4 * i + 3] >= 1000 - 63 && o[4 * i + 3] <= 1000, "min %d returned %d", i, (int)o[4 * i + 3] - 1000);
    CHECK(bad == 0);
    mt_buffer_free(&out);
    mt_buffer_free(&bits);
    pvk_release(t_counters);
    pvk_release(t_minmax);
    pvk_release(t_bits);
    pvk_release(t_vol);
    pvk_release(t_layers);
    pvk_release(t_misc);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Texel buffers ---- */

static void test_texel_buffers(void)
{
    struct pvk_msl_result res;
    struct mt_buffer out, b_ubuf, b_ubuf2, b_sbuf, b_sbuf2;
    struct mt_binding b[5];
    uint8_t px[16 * 4];
    uint32_t u2[16];
    float sb[16 * 4];
    id pso, ubuf, ubuf2, sbuf, sbuf2;
    int i, k;

    for (i = 0; i < 16; i++) {
        px[4 * i + 0] = (uint8_t)(i * 16);
        px[4 * i + 1] = (uint8_t)(255 - i * 16);
        px[4 * i + 2] = (uint8_t)i;
        px[4 * i + 3] = 255;
        u2[i] = (uint32_t)i * 100u;
        for (k = 0; k < 4; k++)
            sb[4 * i + k] = (float)(i * (k + 1));
    }
    MT_BUILD(spv_texelbuf, NULL, res, pso);
    CHECK(res.resource_count == 5 && res.resources[0].type == VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER &&
          res.resources[2].type == VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER && res.resources[2].writable &&
          res.resources[2].stride == 8);
    b_ubuf = mt_buffer(sizeof(px), px, sizeof(px));
    b_ubuf2 = mt_buffer(sizeof(u2), u2, sizeof(u2));
    b_sbuf = mt_buffer(sizeof(sb), sb, sizeof(sb));
    b_sbuf2 = mt_buffer(64, NULL, 0);
    ubuf = mt_texture_buffer(&b_ubuf, PVK_MTLPixelFormatRGBA8Unorm, 16, 4);
    ubuf2 = mt_texture_buffer(&b_ubuf2, PVK_MTLPixelFormatR32Uint, 16, 4);
    sbuf = mt_texture_buffer(&b_sbuf, PVK_MTLPixelFormatRGBA32Float, 16, 16);
    sbuf2 = mt_texture_buffer(&b_sbuf2, PVK_MTLPixelFormatR32Sint, 16, 4);
    out = mt_buffer(17 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, ubuf, NULL);
    b[1] = bind_tex(0, 1, 0, ubuf2, NULL);
    b[2] = bind_tex(0, 2, 0, sbuf, NULL);
    b[3] = bind_tex(0, 3, 0, sbuf2, NULL);
    b[4] = bind(0, 4, &out);
    CHECK(mt_dispatch(pso, &res, b, 5, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 16; i++) {
        const float *o = (const float *)out.data + 4 * i;
        float want[4];
        for (k = 0; k < 4; k++)
            want[k] = (float)px[4 * i + k] / 255.0f + (float)u2[i];
        EXPECT4(o, want, 1e-4f, "texelFetch %d", i);
        for (k = 0; k < 4; k++)
            EXPECT(((float *)b_sbuf.data)[4 * i + k] == 3.0f * sb[4 * i + k], "storage texel buffer %d.%d = %g", i, k,
                   ((float *)b_sbuf.data)[4 * i + k]);
        EXPECT(((int32_t *)b_sbuf2.data)[i] == -7 * i, "write-only texel buffer %d = %d", i, ((int32_t *)b_sbuf2.data)[i]);
    }
    {
        const float *o = (const float *)out.data + 64;
        EXPECT(o[0] == 16 && o[1] == 16 && o[2] == 16 && o[3] == 16, "sizes %g %g %g %g", o[0], o[1], o[2], o[3]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    mt_buffer_free(&b_ubuf);
    mt_buffer_free(&b_ubuf2);
    mt_buffer_free(&b_sbuf);
    mt_buffer_free(&b_sbuf2);
    pvk_release(ubuf);
    pvk_release(ubuf2);
    pvk_release(sbuf);
    pvk_release(sbuf2);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Descriptor arrays: non-uniform indices, runtime arrays, layouts ---- */

static const struct pvk_msl_binding desc_set0[] = {
    { 0, VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, 4, 0, 16, false },
    { 1, VK_DESCRIPTOR_TYPE_SAMPLER, 2, 64, 8, false },
    { 2, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 3, 80, 32, false },
    { 3, VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 2, 176, 16, false },
    { 4, VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER, 2, 208, 8, false },
    { 5, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 4, 224, 16, false },
    { 6, VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 1, 288, 16, false }, /* not used by the shader */
    { 7, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, 304, 16, false },
};
static const struct pvk_msl_binding desc_set1[] = { { 0, VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, 8, 0, 8, true } };

static void run_descriptor_arrays(const uint32_t *words, size_t count, bool layout)
{
    static const struct pvk_msl_set_layout layouts[2] = { { desc_set0, 8 }, { desc_set1, 1 } };
    static const struct mt_sampler_desc unnorm = { PVK_MTLSamplerMinMagFilterNearest, 0,
                                                   PVK_MTLSamplerAddressModeClampToEdge, true, 0 };
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer out, bufs[3], tb[2];
    struct mt_binding b[24];
    id pso, texs[4], smps[2], comb[3], cs[3], imgs[2], tbufs[2], rt[5];
    float t[4 * 4];
    uint32_t n = 0, k, i;

    memset(&options, 0, sizeof(options));
    if (layout) {
        options.set_layouts = layouts;
        options.set_layout_count = 2;
    }
    REQUIRE(mt_translate(words, count, &options, &res));
    CHECK(res.resource_count == 8 && res.set_mask == 3);
    CHECK(res.resources[7].set == 1 && res.resources[7].variable_count && res.resources[7].count == (layout ? 8u : 0u));
    CHECK(res.resources[2].type == VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER &&
          res.resources[2].stride == (layout ? 32u : 16u) && res.resources[2].count == 3);
    pso = mt_pipeline(&res);
    if (!pso)
        pvk_msl_result_free(&res);
    REQUIRE(pso);
    for (k = 0; k < 4; k++) { /* 2x2: texture k texel (x, y) = (k + 1, 10 (k + 1), x, y) */
        for (i = 0; i < 4; i++) {
            t[4 * i + 0] = (float)(k + 1);
            t[4 * i + 1] = (float)(10 * (k + 1));
            t[4 * i + 2] = (float)(i % 2);
            t[4 * i + 3] = (float)(i / 2);
        }
        texs[k] = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 2, 2, 1, 1, 1, 1);
        mt_upload(texs[k], 0, 0, 2, 2, 1, 16, t);
        b[n++] = bind_tex(0, 0, k, texs[k], NULL);
    }
    smps[0] = mt_sampler(&smp_nearest);
    smps[1] = mt_sampler(&unnorm);
    b[n++] = bind_tex(0, 1, 0, NULL, smps[0]);
    b[n++] = bind_tex(0, 1, 1, NULL, smps[1]);
    for (k = 0; k < 3; k++) { /* combined: (100 (k + 1), 0, x, y) */
        for (i = 0; i < 4; i++) {
            t[4 * i + 0] = (float)(100 * (k + 1));
            t[4 * i + 1] = 0.0f;
            t[4 * i + 2] = (float)(i % 2);
            t[4 * i + 3] = (float)(i / 2);
        }
        comb[k] = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 2, 2, 1, 1, 1, 1);
        mt_upload(comb[k], 0, 0, 2, 2, 1, 16, t);
        cs[k] = mt_sampler(&smp_nearest);
        b[n++] = bind_tex(0, 2, k, comb[k], cs[k]);
    }
    for (k = 0; k < 2; k++) {
        uint32_t px[4], tv[4];
        for (i = 0; i < 4; i++) {
            px[i] = 1000u * (k + 1) + i;
            tv[i] = 10000u * (k + 1) + i;
        }
        imgs[k] = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 2, 2, 1, 1, 1, 1);
        mt_upload(imgs[k], 0, 0, 2, 2, 1, 4, px);
        b[n++] = bind_tex(0, 3, k, imgs[k], NULL);
        tb[k] = mt_buffer(sizeof(tv), tv, sizeof(tv));
        tbufs[k] = mt_texture_buffer(&tb[k], PVK_MTLPixelFormatR32Uint, 4, 4);
        b[n] = bind_tex(0, 4, k, tbufs[k], NULL);
        b[n++].buf = &tb[k];
    }
    for (k = 0; k < 3; k++) {
        uint32_t v[8];
        for (i = 0; i < 8; i++)
            v[i] = 100000u * (k + 1) + i;
        bufs[k] = mt_buffer(sizeof(v), v, sizeof(v));
        b[n] = bind(0, 5, &bufs[k]);
        b[n].index = k;
        b[n++].range = (5 + k) * 4; /* lengths 5, 6, 7 */
    }
    for (k = 0; k < 5; k++) {
        float v[4] = { 0.5f * (float)k + 0.25f, 0, 0, 0 };
        rt[k] = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 1, 1, 1, 1, 1, 1);
        mt_upload(rt[k], 0, 0, 1, 1, 1, 16, v);
        b[n++] = bind_tex(1, 0, k, rt[k], NULL);
    }
    out = mt_buffer(64 * 16, NULL, 0);
    b[n++] = bind(0, 7, &out);
    CHECK(mt_dispatch(pso, &res, b, n, NULL, 0, 1, 1, 1));

    bad = 0;
    for (i = 0; i < 64; i++) {
        uint32_t a = i % 4, bb = (i / 4) % 2, c = (i * 7) % 3, d = i % 5;
        const float *o = (const float *)out.data + 4 * i;
        float want[4];
        /* texs[a] sampled at (0.25, 0.75): texel (0, 1) normalized, (0, 0) unnormalized */
        want[0] = (float)(a + 1) + (float)(100 * (c + 1)) + (float)(1000 * (bb + 1) + a);
        want[1] = (float)(10 * (a + 1)) + 0.0f + (float)(10000 * (bb + 1) + a);
        want[2] = 0.0f + 1.0f + (float)(100000 * (c + 1) + a) + (float)(5 + c);
        want[3] = (bb ? 0.0f : 1.0f) + 0.0f + 0.5f * (float)d + 0.25f;
        EXPECT4(o, want, 0.0f, "invocation %u (a %u b %u c %u d %u)", i, a, bb, c, d);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    for (k = 0; k < 4; k++)
        pvk_release(texs[k]);
    for (k = 0; k < 3; k++) {
        pvk_release(comb[k]);
        pvk_release(cs[k]);
        mt_buffer_free(&bufs[k]);
    }
    for (k = 0; k < 2; k++) {
        pvk_release(smps[k]);
        pvk_release(imgs[k]);
        pvk_release(tbufs[k]);
        mt_buffer_free(&tb[k]);
    }
    for (k = 0; k < 5; k++)
        pvk_release(rt[k]);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_descriptor_arrays(void)
{
    run_descriptor_arrays(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), false);
    run_descriptor_arrays(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), true);
}

static void test_descriptor_arrays_opt(void)
{
    run_descriptor_arrays(spv_descarrays_opt, PVK_ARRAY_SIZE(spv_descarrays_opt), true);
}

/* ---- Inline uniform block; image and sampler reading one combined binding ---- */

static void test_inline_uniform_block(void)
{
    static const struct pvk_msl_binding set0[] = {
        { 0, VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK, 32, 0, 0, false },
        { 1, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1, 32, 16, false },
        { 2, VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1, 48, 16, false },
        { 3, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, 64, 16, false },
    };
    static const struct pvk_msl_set_layout layout = { set0, 4 };
    struct {
        float scale[4];
        uint32_t idx[4];
    } block = { { 2, 3, 4, 5 }, { 1, 2, 3, 4 } };
    float add[4] = { 0.5f, 0.25f, 0.125f, 0.0f }, t[16 * 4];
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer out, ubo, ib;
    struct mt_binding b[4];
    id pso, tex, smp;
    int pass, i, k;

    for (i = 0; i < 16; i++) {
        t[4 * i + 0] = (float)(i % 4);
        t[4 * i + 1] = (float)(i / 4);
        t[4 * i + 2] = (float)((i % 4) * (i / 4));
        t[4 * i + 3] = 1.0f;
    }
    tex = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
    mt_upload(tex, 0, 0, 4, 4, 1, 16, t);
    smp = mt_sampler(&smp_nearest);
    ubo = mt_buffer(16, add, 16);
    ib = mt_buffer(sizeof(block), &block, sizeof(block));
    for (pass = 0; pass < 2; pass++) { /* default layout (a uniform buffer), then the inline block */
        memset(&options, 0, sizeof(options));
        if (pass) {
            options.set_layouts = &layout;
            options.set_layout_count = 1;
        }
        MT_BUILD(spv_inline_block, &options, res, pso);
        CHECK(res.resource_count == 4 && res.resources[1].type == VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER &&
              res.resources[0].type ==
                  (pass ? VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK : VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER));
        out = mt_buffer(16 * 16, NULL, 0);
        if (pass) {
            memset(&b[0], 0, sizeof(b[0]));
            b[0].bytes = &block;
            b[0].nbytes = sizeof(block);
        } else {
            b[0] = bind(0, 0, &ib);
        }
        b[1] = bind_tex(0, 1, 0, tex, smp);
        b[2] = bind(0, 2, &ubo);
        b[3] = bind(0, 3, &out);
        CHECK(mt_dispatch(pso, &res, b, 4, NULL, 0, 1, 1, 1));
        bad = 0;
        for (i = 0; i < 16; i++) {
            float want[4];
            for (k = 0; k < 4; k++)
                want[k] = t[4 * i + k] * block.scale[k] + add[k] + (float)block.idx[k];
            EXPECT4((const float *)out.data + 4 * i, want, 0.0f, "pass %d texel %d", pass, i);
        }
        CHECK(bad == 0);
        mt_buffer_free(&out);
        pvk_release(pso);
        pvk_msl_result_free(&res);
    }
    mt_buffer_free(&ubo);
    mt_buffer_free(&ib);
    pvk_release(tex);
    pvk_release(smp);
}

/* ---- 1D images (native and as 2D) and multisampled images ---- */

static void run_image_1d(bool as_2d)
{
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b[5];
    float line[8 * 4], got[8 * 4];
    id pso, t_line, t_ms, t_sline, smp;
    int i, k;
    unsigned long levels = as_2d ? 4 : 1;

    for (i = 0; i < 8; i++) {
        line[4 * i + 0] = (float)i;
        line[4 * i + 1] = (float)(2 * i);
        line[4 * i + 2] = (float)(3 * i);
        line[4 * i + 3] = 1.0f;
    }
    memset(&options, 0, sizeof(options));
    options.image_1d_as_2d = as_2d;
    MT_BUILD(spv_oned, &options, res, pso);
    t_line = mt_texture(as_2d ? PVK_MTLTextureType2D : PVK_MTLTextureType1D, PVK_MTLPixelFormatRGBA32Float, 8, 1, 1, 1,
                        levels, 1);
    t_sline = mt_texture(as_2d ? PVK_MTLTextureType2D : PVK_MTLTextureType1D, PVK_MTLPixelFormatRGBA32Float, 8, 1, 1, 1,
                         1, 1);
    t_ms = mt_texture(PVK_MTLTextureType2DMultisample, PVK_MTLPixelFormatRGBA16Float, 4, 4, 1, 1, 1, 4);
    mt_upload(t_line, 0, 0, 8, 1, 1, 16, line);
    mt_clear(t_ms, 0.25, 0.5, 0.75, 1.0);
    smp = mt_sampler(&smp_nearest);
    out = mt_buffer(8 * 4 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, t_line, smp);
    b[1] = bind_tex(0, 1, 0, t_ms, NULL);
    b[2] = bind_tex(0, 2, 0, NULL, smp);
    b[3] = bind_tex(0, 3, 0, t_sline, NULL);
    b[4] = bind(0, 4, &out);
    CHECK(mt_dispatch(pso, &res, b, 5, NULL, 0, 1, 1, 1));

    bad = 0;
    mt_download(t_sline, 0, 0, 8, 1, 1, 16, got);
    for (i = 0; i < 8; i++) {
        const float *o = (const float *)out.data + 16 * i;
        float want[4];
        int j = i > 0 ? i - 1 : 0;
        EXPECT4(o + 0, &line[4 * i], 0.0f, "1D %s textureLod %d", as_2d ? "as 2D" : "native", i);
        EXPECT4(o + 4, &line[4 * j], 0.0f, "1D %s textureLodOffset %d", as_2d ? "as 2D" : "native", i);
        want[0] = 0.25f + 4.0f; /* the clear color + (size, samples, 0) */
        want[1] = 0.5f + 4.0f;
        want[2] = 0.75f + 4.0f;
        want[3] = 1.0f;
        EXPECT4(o + 8, want, 0.0f, "multisampled fetch %d", i);
        want[0] = 8;
        want[1] = 8;
        want[2] = (float)levels;
        want[3] = 0;
        EXPECT4(o + 12, want, 0.0f, "1D sizes %d", i);
        for (k = 0; k < 4; k++)
            EXPECT(got[4 * i + k] == 2.0f * line[4 * i + k], "storage 1D %d.%d = %g", i, k, got[4 * i + k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(t_line);
    pvk_release(t_sline);
    pvk_release(t_ms);
    pvk_release(smp);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_image_1d_ms(void)
{
    run_image_1d(false);
    run_image_1d(true);
}

/* ---- Images and samplers as function parameters ---- */

static void test_image_functions(void)
{
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b[6];
    float t[3][16 * 4];
    uint32_t zero[2] = { 0, 0 }, counters[2];
    id pso, tex[3], smp;
    int i, k, n;

    MT_BUILD(spv_image_funcs, NULL, res, pso);
    CHECK(res.set_mask == 3 && res.resource_count == 5);
    smp = mt_sampler(&smp_nearest);
    for (n = 0; n < 3; n++) {
        for (i = 0; i < 16; i++)
            for (k = 0; k < 4; k++)
                t[n][4 * i + k] = (float)(100 * n + 10 * k + i);
        tex[n] = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 1, 1, 1);
        mt_upload(tex[n], 0, 0, 4, 4, 1, 16, t[n]);
    }
    b[3] = bind_tex(0, 3, 0, mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 2, 1, 1, 1, 1, 1), NULL);
    mt_upload(b[3].texture, 0, 0, 2, 1, 1, 4, zero);
    out = mt_buffer(16 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, tex[0], smp);
    b[1] = bind_tex(0, 1, 0, tex[1], NULL);
    b[2] = bind_tex(0, 1, 1, tex[2], NULL);
    b[4] = bind_tex(0, 2, 0, NULL, smp);
    b[5] = bind(1, 0, &out);
    CHECK(mt_dispatch(pso, &res, b, 6, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 16; i++) {
        float want[4];
        for (k = 0; k < 4; k++)
            want[k] = t[0][4 * i + k] + t[1 + i % 2][4 * i + k] + (k < 2 ? 4.0f : 0.0f);
        EXPECT4((const float *)out.data + 4 * i, want, 0.0f, "invocation %d", i);
    }
    mt_download(b[3].texture, 0, 0, 2, 1, 1, 4, counters);
    EXPECT(counters[0] == 8 && counters[1] == 8, "counters %u %u", counters[0], counters[1]);
    CHECK(bad == 0);
    mt_buffer_free(&out);
    for (n = 0; n < 3; n++)
        pvk_release(tex[n]);
    pvk_release(b[3].texture);
    pvk_release(smp);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Variables of different types at one binding ---- */

static void test_descriptor_aliases(void)
{
    static const struct mt_sampler_desc less = { PVK_MTLSamplerMinMagFilterNearest, 0, PVK_MTLSamplerAddressModeClampToEdge,
                                                 false, PVK_MTLCompareFunctionLess };
    struct pvk_msl_result res;
    struct mt_buffer words, a[2];
    struct mt_binding b[4];
    uint32_t init[80], av[2][40], i;
    float d[16];
    id pso, depth, smp;

    for (i = 0; i < 80; i++)
        init[i] = i < 64 ? i * 3 + 1 : 0;
    for (i = 0; i < 40; i++) {
        av[0][i] = 7 * i;
        av[1][i] = 7 * i + 50;
    }
    for (i = 0; i < 16; i++)
        d[i] = (float)i / 16.0f + 1.0f / 64.0f;
    MT_BUILD(spv_aliases, NULL, res, pso);
    CHECK(res.resource_count == 3 && res.resources[1].count == 2 &&
          res.resources[2].type == VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER);
    words = mt_buffer(sizeof(init), init, sizeof(init));
    a[0] = mt_buffer(sizeof(av[0]), av[0], sizeof(av[0]));
    a[1] = mt_buffer(sizeof(av[1]), av[1], sizeof(av[1]));
    depth = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatDepth32Float, 4, 4, 1, 1, 1, 1);
    mt_upload(depth, 0, 0, 4, 4, 1, 4, d);
    smp = mt_sampler(&less);
    b[0] = bind(0, 0, &words);
    b[1] = bind(0, 1, &a[0]);
    b[1].range = 24 * 4;
    b[2] = bind(0, 1, &a[1]);
    b[2].index = 1;
    b[3] = bind_tex(0, 2, 0, depth, smp);
    CHECK(mt_dispatch(pso, &res, b, 4, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 16; i++) {
        uint32_t want = init[4 * i] + init[4 * i + 3] + av[i % 2][i] + av[1][2 * i + 1] + 12 + i * 1000 +
                        (0.5f < d[i] ? 100000u : 0u);
        EXPECT(((uint32_t *)words.data)[64 + i] == want, "w[%u] = %u, want %u", 64 + i, ((uint32_t *)words.data)[64 + i],
               want);
    }
    CHECK(bad == 0);
    mt_buffer_free(&words);
    mt_buffer_free(&a[0]);
    mt_buffer_free(&a[1]);
    pvk_release(depth);
    pvk_release(smp);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ---- Layout and image errors fail cleanly ---- */

/* Translates with set 0 laid out by bindings[0, n) and set 1 by set1 (if
 * nsets > 1): VK_SUCCESS (needle NULL) or a failure mentioning needle. */
static bool layout_result(const uint32_t *words, size_t count, const struct pvk_msl_binding *bindings, uint32_t n,
                          const struct pvk_msl_set_layout *set1, uint32_t nsets, const char *needle)
{
    struct pvk_msl_set_layout sl[2];
    struct pvk_msl_options options;
    struct pvk_msl_result res;
    VkResult r;
    bool ok;
    memset(&options, 0, sizeof(options));
    sl[0].bindings = bindings;
    sl[0].binding_count = n;
    if (set1)
        sl[1] = *set1;
    options.set_layouts = sl;
    options.set_layout_count = nsets;
    r = pvk_spirv_to_msl(words, count, NULL, &options, &res);
    if (!needle)
        ok = r == VK_SUCCESS && res.msl != NULL;
    else
        ok = r == VK_ERROR_INITIALIZATION_FAILED && res.msl == NULL && strstr(res.error, needle) != NULL;
    if (!ok)
        fprintf(stderr, "  result %d, error \"%s\", expected \"%s\"\n", (int)r, res.error, needle ? needle : "");
    pvk_msl_result_free(&res);
    return ok;
}

static void test_reject_layouts(void)
{
    struct pvk_msl_binding l[4] = {
        { 0, VK_DESCRIPTOR_TYPE_INLINE_UNIFORM_BLOCK, 32, 0, 0, false },
        { 1, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1, 32, 16, false },
        { 2, VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1, 48, 16, false },
        { 3, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, 64, 16, false },
    };
    const uint32_t *w = spv_inline_block;
    size_t n = PVK_ARRAY_SIZE(spv_inline_block);

    CHECK(layout_result(w, n, l, 4, NULL, 1, NULL)); /* the valid layout translates */
    CHECK(layout_result(w, n, l, 3, NULL, 1, "not in the set layout"));
    CHECK(layout_result(w, n, l, 4, NULL, 0, "does not have"));
    l[2].type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "does not match"));
    l[2].type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "does not match"));
    l[2].type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
    l[1].type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE; /* the sampler half needs a sampler or combined binding */
    CHECK(layout_result(w, n, l, 4, NULL, 1, "does not match"));
    l[1].type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    l[2].offset = 40; /* overlaps the combined descriptor */
    CHECK(layout_result(w, n, l, 4, NULL, 1, "overlaps"));
    l[2].offset = 52;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "not aligned"));
    l[2].offset = 48;
    l[1].count = 0;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "descriptors"));
    l[1].count = 2;
    l[1].stride = 12;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "stride"));
    l[1].count = 1;
    l[0].type = VK_DESCRIPTOR_TYPE_MUTABLE_EXT;
    CHECK(layout_result(w, n, l, 4, NULL, 1, "descriptor type"));
    {
        struct pvk_msl_binding d[8];
        struct pvk_msl_set_layout set1 = { desc_set1, 1 };
        memcpy(d, desc_set0, sizeof(d));
        CHECK(layout_result(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), d, 8, &set1, 2, NULL));
        d[0].count = 2; /* texs[4] */
        CHECK(layout_result(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), d, 8, &set1, 2, "descriptors"));
        d[0].count = 4;
        d[7].offset = 240; /* out of offset order */
        CHECK(layout_result(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), d, 8, &set1, 2, "overlaps"));
        d[7].offset = 304;
        set1.binding_count = 0; /* the runtime array's set lacks it */
        CHECK(layout_result(spv_descarrays, PVK_ARRAY_SIZE(spv_descarrays), d, 8, &set1, 2, "not in the set layout"));
    }
}

