    struct mt_buffer bi, bo;
    struct mt_binding b[2];
    id pso;

    MT_BUILD(spv_member_group, NULL, res, pso);
    bi = mt_buffer(sizeof(in), in, sizeof(in));
    bo = mt_buffer(sizeof(out), out, sizeof(out));
    b[0] = bind(0, 0, &bi);
    b[1] = bind(0, 1, &bo);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
