/* Pointer comparisons of row-major matrices and their columns (no MSL
 * object of their type to take the address of). */
static void test_ptr_compare_rows(void)
{
    uint32_t out[4] = { 9, 9, 9, 9 };
    float data[32];
    struct pvk_msl_result res;
    struct mt_buffer bd, bo;
    struct mt_binding b[2];
    id pso;

    memset(data, 0, sizeof(data));
    MT_BUILD(spv_ptr_compare_rows, NULL, res, pso);
    bd = mt_buffer(sizeof(data), data, sizeof(data));
    bo = mt_buffer(sizeof(out), out, sizeof(out));
    b[0] = bind(0, 0, &bd);
    b[1] = bind(0, 1, &bo);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    CHECK(get_u32(bo.data, 0) == 1 && get_u32(bo.data, 4) == 0);
    CHECK(get_u32(bo.data, 8) == 1 && get_u32(bo.data, 12) == 1);
    mt_buffer_free(&bd);
    mt_buffer_free(&bo);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

