/* Signed integer arithmetic wraps (SPIR-V), where MSL's signed overflow is
 * undefined and its compiler folds on it: INT_MIN - 1 is INT_MAX (one loop
 * iteration, not none), -INT_MIN and INT_MIN * 2 wrap. */
static void test_wrapping_arithmetic(void)
{
    int32_t init[4] = { 1, 0, 0, 0 };
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    id pso;

    MT_BUILD(spv_wrapping_arithmetic, NULL, res, pso);
    buf = mt_buffer(sizeof(init), init, sizeof(init));
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    CHECK(get_u32(buf.data, 4) == 1u);
    CHECK(get_u32(buf.data, 8) == 0x80000000u && get_u32(buf.data, 12) == 0u);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

