/* A function returning from a loop and after it, called with a uniform
 * argument: Metal's compiler returned 0 for it inlined (not inlined now). */
static void test_loop_return_uniform(void)
{
    float init[2] = { -0.5f, 7.0f };
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    id pso;

    MT_BUILD(spv_loop_return, NULL, res, pso);
    buf = mt_buffer(sizeof(init), init, sizeof(init));
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    CHECK(((const float *)buf.data)[1] == 0.5f);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}


