/* Atomics on vector components (MSL takes no address of one). */
static void test_atomic_components(void)
{
    uint32_t init[4] = { 0, 0, 0, 0 };
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    id pso;

    MT_BUILD(spv_atomic_components, NULL, res, pso);
    buf = mt_buffer(sizeof(init), init, sizeof(init));
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    CHECK(get_u32(buf.data, 0) == 0xfu && get_u32(buf.data, 8) == 4);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

