/* IEEE special values (shaderSignedZeroInfNanPreserve, float_controls2
 * without fast-math flags), where Metal's functions answer otherwise. The
 * module declares SignedZeroInfNanPreserve: without float controls Vulkan
 * gives none of these, and the wrappers are the plain functions. */
static void test_ieee_specials(void)
{
    struct pvk_msl_result res;
    struct mt_buffer buf;
    struct mt_binding b;
    uint32_t bits[20], i;
    float in[4], *o;
    id pso;

    bits[0] = 0x7f800000u; /* inf */
    bits[1] = 0x80000000u; /* -0 */
    bits[2] = 0x7fc00000u; /* NaN */
    memcpy(in, bits, sizeof(in));
    in[3] = 1.0f;
    MT_BUILD(spv_ieee_specials, NULL, res, pso);
    buf = mt_buffer(20 * 4, in, sizeof(in));
    b = bind(0, 0, &buf);
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, 1, 1, 1));
    o = (float *)buf.data + 4;
    memcpy(bits, o, 14 * 4);
    bad = 0;
    for (i = 0; i < 3; i++)
        EXPECT(isnan(o[i]), "o[%u] = %g, want NaN", i, (double)o[i]);
    EXPECT(bits[3] == 0xff800000u, "asinh(-inf) = %08x", bits[3]);
    EXPECT(bits[4] == 0x80000000u, "round(-0) = %08x", bits[4]);
    EXPECT(bits[5] == 0x80000000u, "min(-0, 0) = %08x", bits[5]);
    EXPECT(bits[6] == 0x00000000u, "max(0, -0) = %08x", bits[6]);
    EXPECT(isnan(o[7]), "tanh(NaN) = %g", (double)o[7]);
    EXPECT(o[8] == (float)-3.14159265358979323846, "atan(-0, -1) = %.9g", (double)o[8]);
    EXPECT(o[9] == (float)(3.0 * 3.14159265358979323846 / 4.0), "atan(inf, -inf) = %.9g", (double)o[9]);
    EXPECT(bits[10] == 0x80000000u, "frexp(-0) = %08x", bits[10]);
    EXPECT(bits[11] == 0x80000000u, "(-0 matrix) * v = %08x", bits[11]);
    EXPECT(isnan(o[12]), "cos(NaN) = %g", (double)o[12]);
    EXPECT(o[13] == (float)(-3.14159265358979323846 / 4.0), "atan(-inf, inf) = %.9g", (double)o[13]);
    CHECK(bad == 0);
    mt_buffer_free(&buf);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

