/* Arrays of arrays of row-major matrices (lines 48 bytes apart, each array
 * of them 144), a rotate cluster larger than the subgroup in code for
 * larger subgroups, and block members out of offset order. */
static void test_layout_odds(void)
{
    struct pvk_msl_result res;
    struct mt_buffer m, o;
    struct mt_binding b[2];
    float in[72], init[6] = { 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f };
    uint32_t i, *r;
    id pso;

    MT_BUILD(spv_matrix_arrays_rotate, NULL, res, pso);
    for (i = 0; i < 72; i++)
        in[i] = (float)i;
    m = mt_buffer(sizeof(in), in, sizeof(in));
    o = mt_buffer(33 * 4, NULL, 0);
    b[0] = bind(0, 0, &m);
    b[1] = bind(0, 1, &o);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    CHECK(get_f32(o.data, 0) == 67.0f); /* matrix [1][2], column 3 row 1: (5 * 48 + 16 + 12) / 4 */
    r = (uint32_t *)o.data + 1;
    bad = 0;
    for (i = 0; i < 32; i++)
        EXPECT(r[i] == ((i & ~7u) | ((i + 1u) & 7u)), "rotate lane %u: %u", i, r[i]);
    CHECK(bad == 0);
    mt_buffer_free(&m);
    mt_buffer_free(&o);
    pvk_release(pso);
    pvk_msl_result_free(&res);

    MT_BUILD(spv_offset_order, NULL, res, pso);
    m = mt_buffer(sizeof(init), init, sizeof(init));
    b[0] = bind(0, 0, &m);
    CHECK(mt_dispatch(pso, &res, b, 1, NULL, 0, 1, 1, 1));
    CHECK(get_f32(m.data, 20) == 7.0f && get_f32(m.data, 16) == 5.0f && get_f32(m.data, 4) == 2.0f);
    mt_buffer_free(&m);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

