/* Scalar block layout placed tighter than MSL types align: a struct of 10
 * bytes holding uints, followed at offset 10 (a packed struct); a vec4 array
 * at 12 and a row-major mat4x2 at 44 (packed lines); a struct at 80, whose
 * rows would align to 16, with the next member right after its 44 bytes. */
static void test_layout_tight(void)
{
    struct pvk_msl_result res;
    struct mt_buffer m;
    struct mt_binding b[1];
    unsigned char d[128];
    uint32_t u[2] = { 3, 5 };
    float a0[4] = { 1, 2, 3, 4 };
    id pso;
    int i;

    MT_BUILD(spv_layout_tight, NULL, res, pso);
    memset(d, 0, sizeof(d));
    memcpy(d, u, 8);
    d[8] = 7;
    d[9] = 9;
    d[10] = 2;
    memcpy(d + 12, a0, 16);
    put_f32(d, 44, 0.5f);    /* m[0][0] */
    put_f32(d, 76, 11.0f);   /* p */
    put_f32(d, 108, 0.25f);  /* n.m[3][1]: row 1, column 3 */
    put_f32(d, 120, 0.125f); /* n.v.z */
    m = mt_buffer(sizeof(d), d, sizeof(d));
    b[0] = bind(0, 0, &m);
    CHECK(mt_dispatch(pso, &res, b, 1, NULL, 0, 1, 1, 1));
    CHECK(get_f32(m.data, 124) == 2953.0f);
    for (i = 0; i < 4; i++)
        CHECK(get_f32(m.data, 28 + 4 * i) == a0[i] + 1.0f);
    CHECK(get_f32(m.data, 72) == 0.875f && get_f32(m.data, 112) == 11.0f && get_f32(m.data, 76) == 11.0f);
    CHECK(((unsigned char *)m.data)[8] == 10 && ((unsigned char *)m.data)[10] == 2);
    mt_buffer_free(&m);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

