/* textureGrad on a cube: Vulkan's level from the derivatives of the face
 * coordinates around the major axis (8x8 faces: levels 0, 1, 2, 2, 1; each
 * level reads its number, nearest mip filtering). */
static void test_cube_grad(void)
{
    static const float want[5] = { 0.0f, 1.0f, 2.0f, 2.0f, 1.0f };
    static float level[64 * 4];
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b[2];
    uint32_t l, f, i;
    id pso, tex, smp;

    MT_BUILD(spv_cube_grad, NULL, res, pso);
    tex = mt_texture(PVK_MTLTextureTypeCube, PVK_MTLPixelFormatRGBA32Float, 8, 8, 1, 1, 4, 1);
    for (l = 0; l < 4; l++) {
        for (i = 0; i < 64; i++) {
            level[4 * i] = (float)l;
            level[4 * i + 1] = level[4 * i + 2] = 0.0f;
            level[4 * i + 3] = 1.0f;
        }
        for (f = 0; f < 6; f++)
            mt_upload(tex, l, f, 8u >> l, 8u >> l, 1, 16, level);
    }
    smp = mt_sampler(&smp_nearest);
    out = mt_buffer(5 * 16, NULL, 0);
    b[0] = bind_tex(0, 0, 0, tex, smp);
    b[1] = bind(0, 1, &out);
    CHECK(mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1));
    bad = 0;
    for (i = 0; i < 5; i++)
        EXPECT(get_f32(out.data, 16 * i) == want[i], "textureGrad %u read level %g, want %g", i,
               (double)get_f32(out.data, 16 * i), (double)want[i]);
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(tex);
    pvk_release(smp);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_reject_image_ops(void)
{
    CHECK(fails_with(spv_reject_deriv, PVK_ARRAY_SIZE(spv_reject_deriv), "derivatives"));
    CHECK(fails_with(spv_reject_fatomic, PVK_ARRAY_SIZE(spv_reject_fatomic), "float image atomics"));
}

